/* Original advanced teaching layer for the 50 core lessons. All cases are hypothetical. */
(function(){
  'use strict';
  const seminars={};
  const S=(title,text)=>({title,text});
  const F=(code,symbols,use,limits)=>({code,symbols,use,limits});
  const add=(course,id,sections,title,facts,steps,decision,formula)=>{
    (seminars[course]??={})[id]={sections,title,facts,steps,decision,formula};
  };
  add('ethics','ethical-framework',[
    S('Nghĩa vụ với ai, trong vai trò nào?|To whom do you owe duties?', 'Trước khi chọn hành động, xác định bạn đang là analyst, manager, employee hay trustee và ai là client thực sự. Với quỹ hưu trí, người điều hành thuê bạn không nhất thiết là đối tượng cuối cùng cần bảo vệ; người hưởng quyền lợi cũng liên quan. Tách lợi ích khách, công ty và cá nhân để thấy xung đột.|Before acting, identify whether you are an analyst, manager, employee or trustee and who the client actually is. A pension plan’s hiring executive is not necessarily the ultimate beneficiary. Separating client, employer and personal interests reveals conflicts.'),
    S('Khung quyết định khi thông tin thiếu|Deciding with incomplete information','Lập danh sách sự kiện đã xác minh, sự kiện còn nghi ngờ và thời gian cần hành động. Xét phương án làm, trì hoãn, từ chối hoặc chuyển cấp; đánh giá tác động lên người chịu rủi ro. Nếu hành động không thể giải thích trung thực cho khách thì cần xem lại trước khi thực hiện.|List verified facts, uncertainties and deadlines. Compare acting, delaying, refusing and escalating, including effects on those bearing risk. An action that cannot be honestly explained to clients needs reconsideration.'),
    S('Từ chối và tách khỏi hành vi vi phạm|Refusal and dissociation','Khi biết hoạt động trái yêu cầu áp dụng, không chỉ ghi một disclaimer rồi tiếp tục. Làm rõ, xin hướng dẫn compliance hoặc legal, từ chối phần vi phạm và tách khỏi hành vi nếu cần. Nghĩa vụ báo cơ quan bên ngoài tùy luật; không tự giả định mọi vụ đều phải công khai.|A disclaimer does not permit continued participation in known misconduct. Clarify, seek compliance or legal guidance, refuse the improper act and dissociate where needed. External reporting duties depend on applicable law rather than a universal public-disclosure rule.')
  ],'Đổi nhãn expense để giữ khách vay|Relabeling expense to retain a borrower',
    'Finance director muốn chuyển chi phí marketing hợp lệ 200 sang tài sản để tránh breach covenant; khách hàng ngân hàng chưa được thông báo.|The finance director wants to capitalize 200 of valid marketing expense to avoid a covenant breach; the bank has not been informed.',
    ['Xác định bản chất và chuẩn ghi nhận, không bắt đầu từ mục tiêu covenant.|Identify the substance and accounting rule, not the desired covenant outcome.','Nếu không đáp ứng capitalization, giữ expense và tính lại covenant bằng số đúng.|If capitalization criteria fail, retain the expense and recalculate the covenant.','Lưu yêu cầu, từ chối bút toán sai và chuyển cấp phù hợp; đánh giá phương án waiver với dữ kiện trung thực.|Document, refuse the improper entry and escalate; evaluate a waiver using truthful information.'],
    'Thiếu tiền hoặc sợ mất khách không làm thay đổi bản chất kế toán. Giải pháp kinh doanh là đàm phán, không tạo thông tin sai.|Cash pressure or client retention does not change accounting substance. Negotiate commercially using accurate information.');
  add('ethics','mnpi',[
    S('Đánh giá materiality theo nội dung và nguồn|Assess content and source','Kết quả merger đã chốt, mất khách lớn hoặc earnings chưa công bố có thể trọng yếu. Độ chắc chắn, quy mô ảnh hưởng và độ tin cậy nguồn cùng quan trọng. Tin càng đáng tin không có nghĩa càng được phép dùng để trade; đôi khi điều đó làm vấn đề nghiêm trọng hơn.|Final merger terms, loss of a major customer or unpublished earnings may be material. Certainty, magnitude and source reliability matter together. Greater reliability does not grant permission to trade and can strengthen the concern.'),
    S('Khi nào được coi là công khai?|When is information public?','Một nhóm chat, buổi gặp riêng hoặc tin đồn không tự là phổ biến rộng rãi. Kiểm tra cách công ty công bố và thị trường có cơ hội tiếp cận. Không dùng một thời gian chờ cố định cho mọi thị trường; phối hợp compliance trước khi gỡ hạn chế.|A private meeting, chat group or rumor is not automatically broad dissemination. Examine the release channel and reasonable market access. Do not use one universal waiting period; coordinate with compliance before removing restrictions.'),
    S('Mosaic cần nguồn không bị ô nhiễm|Mosaic needs a clean information basis','Bạn có thể suy nhu cầu từ giá niêm yết, khảo sát khách và số liệu công khai; kết luận riêng có thể rất giá trị. Nhưng nhận thêm số earnings bí mật rồi gọi toàn bộ kết luận là mosaic không giải quyết vấn đề. Tách và ghi rõ nguồn để kiểm chứng quá trình.|You can infer demand from public prices, surveys and disclosures. A valuable original conclusion can be legitimate. Adding confidential earnings and calling the result mosaic does not cleanse it; document the sources and process.')
  ],'Mua ít có tránh được hạn chế?|Does a small trade avoid restrictions?',
    'Analyst biết riêng công ty sắp mất hợp đồng tạo 35% revenue. Giá chưa phản ánh; cô muốn bán chỉ 5% cổ phiếu cá nhân.|An analyst privately learns that a contract representing 35% of revenue will be lost. She wants to sell only 5% of her personal holding.',
    ['Đánh giá mất hợp đồng có thể quan trọng với investor hợp lý.|Assess why the lost contract matters to a reasonable investor.','Xác định thông tin chưa được phổ biến rộng và có nguồn cụ thể.|Confirm that the specific information is not broadly public.','Không trade hoặc tip; báo compliance và quản lý research chứa thông tin theo quy trình.|Do not trade or tip; notify compliance and handle affected research appropriately.'],
    'Quy mô 5% không biến cơ sở thông tin thành hợp lệ. Cả tài khoản khách và cá nhân đều cần xử lý vấn đề.|The 5% size does not legitimize the information basis; both client and personal accounts require proper handling.');
  add('ethics','client-duties',[
    S('Suitability theo toàn danh mục|Suitability in the total portfolio','Một chứng khoán rủi ro cao có thể là phần nhỏ của danh mục phù hợp, nhưng một sản phẩm an toàn riêng lẻ vẫn có thể sai vì khóa tiền quá lâu. Đánh giá allocation sau giao dịch, concentration, horizon và cash obligations; không chỉ gắn nhãn sản phẩm conservative hay aggressive.|A risky security may fit a small portfolio sleeve, while a nominally safe locked product may not meet cash needs. Evaluate the post-trade allocation, concentration, horizon and obligations rather than product labels alone.'),
    S('Advisory và mandate có phạm vi khác|Advisory versus mandate constraints','Khi quản lý theo mandate xác định, bạn phải giữ giao dịch đúng mandate. Khi có quan hệ advisory, thu thập hoàn cảnh khách và cập nhật thay đổi trước recommendation phù hợp. Lệnh khách muốn thực hiện không tự làm mất nghĩa vụ trao đổi về sự không phù hợp.|A defined mandate constrains portfolio trades. In advisory relationships, learn and update client circumstances before recommending. A client’s request does not automatically remove the duty to address suitability concerns.'),
    S('Fair dealing khác ưu ái|Fair dealing versus favoritism','Thông tin recommendation phải được phân phối công bằng theo chính sách; cấp dịch vụ khác có thể tồn tại nếu công bố phù hợp. Phân bổ IPO không dựa tài khoản mang lại quà hoặc phí giới thiệu cho analyst. Lưu tiêu chí trước khi biết lợi nhuận giao dịch.|Recommendations should be distributed fairly under policy; properly disclosed service levels may differ. IPO allocations should not favor accounts that benefit the analyst personally. Establish criteria before seeing trade profits.')
  ],'Sản phẩm hấp dẫn và nghĩa vụ học phí|An attractive product and tuition liability',
    'Khách có 2 tỷ, cần 600 triệu sau 8 tháng; muốn đầu tư 1,8 tỷ vào quỹ private khóa ba năm.|A client has 2 billion, owes 600 million in eight months and wants 1.8 billion in a three-year locked private fund.',
    ['Sau đầu tư chỉ còn 200 triệu liquid, thiếu 400 triệu trước buffer.|Only 200 million would remain liquid, a 400 million shortfall before buffers.','Tách nghĩa vụ chắc chắn khỏi phần thực sự có horizon dài.|Separate the known obligation from genuinely long-horizon wealth.','Điều chỉnh size, nguồn tài trợ hoặc lựa chọn sản phẩm; ghi thay đổi IPS nếu hoàn cảnh mới hợp lệ.|Adjust size, funding or product and document justified IPS changes.'],
    'Expected return cao không bù được mismatch cash đã biết. Hãy giải bài toán tài trợ trước return.|High expected return does not resolve a known cash mismatch; fund the obligation first.');
  add('ethics','research-basis',[
    S('Kiểm tra dữ liệu và mô hình độc lập|Independently inspect data and models','Model mua ngoài hay AI vẫn cần hiểu input, assumptions, validation và giới hạn. Không nhất thiết tự viết mọi thuật toán nhưng phải có cơ sở hợp lý để dựa vào nó. Với black box không kiểm chứng được, hạ mức tin cậy hoặc không dùng để recommendation.|Third-party and AI models need input, assumption, validation and limitation checks. You need not write every algorithm but need a reasonable basis for relying on it. Unverifiable black boxes may require reduced reliance or rejection.'),
    S('Fact, forecast và opinion|Facts, forecasts and opinions','Revenue đã công bố là dữ kiện theo nguồn; growth dự kiến là forecast; kết luận cổ phiếu rẻ là judgment. Tách ba lớp giúp khách hiểu cái gì đã biết và cái gì có thể sai. Nêu thay đổi phương pháp và rủi ro trọng yếu khi cập nhật research.|Reported revenue is a sourced fact; projected growth is a forecast; cheapness is judgment. Separating the three shows what is known and uncertain. Communicate material method changes and risks in updates.'),
    S('Research có thể tái lập|Reproducible research','Lưu phiên bản dữ liệu, model, assumptions và quyết định để người khác tái lập tại thời điểm phát hành. Một dashboard hiện tại không chứng minh dữ liệu đã có trong quá khứ. Retention records tuân theo luật và chính sách áp dụng.|Keep data versions, models, assumptions and decisions to reproduce the recommendation as issued. Today’s dashboard does not establish historical data availability. Retain records under applicable law and policy.')
  ],'Forecast tăng do đổi định nghĩa|Growth from a definition change',
    'Revenue tăng 25% nhưng năm trước báo net, năm nay báo gross; analyst chưa đọc notes và muốn công bố growth acceleration.|Revenue rises 25%, but reporting changed from net to gross. An analyst plans to announce accelerating growth without reading the notes.',
    ['Xác định thay đổi principal-agent và accounting presentation.|Identify the principal-agent and presentation change.','Chuẩn hóa cùng cơ sở; kiểm tra economics và cash có tăng tương ứng.|Restate comparably and check underlying economics and cash.','Tách reported growth khỏi normalized growth, công bố giới hạn so sánh.|Distinguish reported and normalized growth and explain comparability limits.'],
    'Giữ recommendation đến khi có reasonable basis; headline growth riêng lẻ không đủ.|Withhold the recommendation until it has a reasonable basis; headline growth is insufficient.');
  add('ethics','conflicts',[
    S('Tránh hoặc công bố xung đột|Avoid or disclose conflicts','Xung đột có thể thực tế hoặc đủ lớn để ảnh hưởng nhận định khách. Công bố phải dễ thấy, đủ nội dung và đúng thời điểm; chôn trong điều khoản dài không giúp khách đánh giá. Một số hành vi cần tránh, chứ không được phép chỉ vì đã công bố.|Conflicts can be actual or reasonably relevant to client judgment. Disclosure must be prominent, informative and timely. Some conduct must be avoided rather than merely disclosed.'),
    S('Quà và thù lao bổ sung|Gifts and additional compensation','Phân biệt quà từ bên muốn tác động research với phần thưởng khách cho kết quả đã làm. Cả hai cần xem ảnh hưởng độc lập và nghĩa vụ với employer; additional compensation có yêu cầu chấp thuận theo chuẩn. Không dùng một mức tiền quà chung cho mọi trường hợp.|Distinguish gifts seeking influence from client rewards for completed work. Both can affect independence and employer duties; additional compensation has consent requirements. No universal gift-value threshold resolves every case.'),
    S('Front-running và trade allocation|Front-running and allocation','Đặt lệnh cá nhân trước lệnh khách để hưởng tác động giá là vấn đề ưu tiên giao dịch. Cách chia order phải xác định trước, có tiêu chí phù hợp và nhất quán. Không phân các fills tốt cho người thân sau khi biết giá thực hiện.|Trading personally ahead of client orders to benefit from impact violates priority duties. Allocation should follow pre-established consistent criteria, not assign favorable fills to relatives after execution.')
  ],'Referral fee bị giấu trong recommendation|A hidden referral fee',
    'Analyst giới thiệu một quỹ và được trả 1% vốn khách đầu tư, nhưng chỉ nói đó là “quỹ đối tác”.|An analyst receives 1% of client subscriptions for recommending a fund but calls it only a partner fund.',
    ['Nhận diện lợi ích tài chính có thể làm lệch recommendation.|Identify the financial benefit that may bias advice.','Công bố bản chất và giá trị hoặc cơ sở tính phí theo yêu cầu phù hợp, trước khi khách quyết định.|Disclose the nature and amount or basis of fees as required before the decision.','Kiểm tra suitability và nghĩa vụ employer độc lập với disclosure.|Separately assess suitability and employer obligations.'],
    'Gọi “đối tác” không cho khách đủ thông tin về incentive; disclosure cũng không thay thế suitability.|Calling it a partner does not explain the incentive, and disclosure does not replace suitability.');

  add('quantitative','tvm',[
    S('Dựng timeline trước công thức|Draw the timeline first','Đặt t=0 ở ngày định giá; chỉ rõ cash cuối hay đầu kỳ. Annuity due sớm hơn ordinary annuity một kỳ nên PV khác. Dòng không đều cần chiết khấu từng khoản, không lấy trung bình CF rồi nhân số kỳ. Đặt dấu từ góc nhìn người đầu tư.|Set time zero at valuation and mark beginning versus end payments. An annuity due arrives one period earlier than an ordinary annuity. Uneven flows require individual discounting; choose signs from the investor’s perspective.'),
    S('Compounding và effective rate|Compounding and effective rates','Lãi danh nghĩa chia m cho periodic rate chỉ khi đó là quote nominal compounded m lần. Effective annual rate phản ánh compound; lãi thực loại lạm phát. Cash nominal phải dùng rate nominal cùng currency và horizon; không giảm inflation hai lần.|Divide a nominal quote by compounding frequency only under that quotation convention. Effective annual rate includes compounding; real rates remove inflation. Match nominal cash with nominal rates in the same currency and horizon.'),
    S('Discount rate và claim|Discount rates and claims','Một khoản chắc chắn và startup cash flow không dùng cùng required return chỉ vì cùng năm nhận tiền. Suất cần khớp rủi ro và quyền của claim. Cân nhắc scenario cash cùng probability trước khi chọn rate; không vừa haircut bất hợp lý vừa tăng rate cho cùng rủi ro mà không giải thích.|Certain payments and startup cash need different risk treatment. Match required return to the claim and cash risk. Explain scenario probabilities and avoid double-counting a risk through arbitrary cash haircuts and rates.')
  ],'So hai cách thanh toán máy|Compare two machine payment plans',
    'Trả ngay 100 triệu hoặc trả 55 triệu cuối năm 1 và 55 triệu cuối năm 2. Chi phí vốn phù hợp 10%/năm; không phí khác.|Pay 100 million now or 55 million at each of the next two year-ends, using a suitable 10% annual rate and no fees.',
    ['Hai khoản trả chậm có PV 50 và khoảng 45,455 triệu.|The deferred payments have PVs of 50 and about 45.455 million.','Tổng PV 95,455 triệu thấp hơn trả ngay 100 triệu.|Combined PV is 95.455 million versus 100 now.','Theo giả định, trả chậm tiết kiệm PV khoảng 4,545 triệu; kiểm tra phí và liquidity trước ký.|Deferral saves about 4.545 million in PV; check fees and liquidity.'],
    'So sánh cùng ngày mới có ý nghĩa; tổng danh nghĩa 110 lớn hơn 100 không tự làm trả chậm đắt hơn về PV.|Compare at one date: nominal 110 exceeding 100 does not alone make deferral more expensive in PV.',
    F('PV=frac(CF₁;1+r)+frac(CF₂;(1+r)²)','PV: giá hiện tại; CF₁, CF₂: thanh toán cuối năm; r: effective annual discount rate.|PV: present value; CF₁, CF₂: end-year payments; r: effective annual discount rate.','Thay CF bằng 55 và r bằng 0,10 để tái lập ví dụ.|Use CF of 55 and r of 0.10 to reproduce the case.','Giả sử dòng tiền và rate cùng cơ sở nominal/real, tiền tệ và rủi ro.|Match nominal/real basis, currency and risk.'));
  add('quantitative','probability',[
    S('Joint, conditional và total probability|Joint, conditional and total probability','Joint hỏi hai sự kiện cùng xảy ra; conditional hỏi một sự kiện khi đã biết sự kiện kia. Total probability cộng các nhánh loại trừ và bao quát. Independence nghĩa conditional bằng unconditional; mutually exclusive lại không thể cùng xảy ra, hai khái niệm khác nhau.|Joint probability concerns simultaneous events; conditional probability uses a known event. Total probability combines exhaustive exclusive branches. Independence is different from mutual exclusivity.'),
    S('Bayes cập nhật chứ không thay prior tùy ý|Bayes updates rather than replaces priors','Một tín hiệu tốt có thể chủ yếu đến từ nhóm không tốt nếu base rate nhóm tốt rất nhỏ. Lập bảng 100 hoặc 1.000 trường hợp giúp thấy false positives. Likelihood của tín hiệu phải riêng cho từng trạng thái, không nhầm với posterior cần tìm.|A positive signal may mostly come from bad cases when good cases are rare. A frequency table exposes false positives. Signal likelihood under each state is not the posterior being estimated.'),
    S('Kỳ vọng và quyết định dưới downside|Expectation and downside','Expected profit không mô tả xác suất hết vốn. Cùng kỳ vọng có thể có distribution khác, nhất là skew và tail. Khi đánh giá decision, nối probabilities với capacity, repeated bets và liquidity; expected value dương không phải điều kiện đủ.|Expected profit does not describe ruin probability. Equal expectations can have different skew and tails. Decisions also require loss capacity, repeated exposure and liquidity.')
  ],'Tín hiệu tăng trưởng đáng tin đến đâu?|How reliable is a growth signal?',
    '30% doanh nghiệp thực sự tăng trưởng cao. Test báo tốt với 80% nhóm cao và 20% nhóm còn lại.|30% of firms truly have high growth. A test is positive for 80% of high-growth firms and 20% of the rest.',
    ['Trong 1.000 doanh nghiệp, có 300 nhóm cao; 240 test tốt.|Among 1,000 firms, 300 are high growth and 240 test positive.','Trong 700 còn lại, 140 test tốt; tổng positive 380.|Of the other 700, 140 test positive, giving 380 positives.','Posterior nhóm cao khi test tốt là 240/380, khoảng 63,16%.|The high-growth posterior after a positive test is about 63.16%.'],
    'Test tốt cải thiện prior 30% nhưng không bảo đảm 80% hay 100% thành công.|The positive signal improves the 30% prior but does not imply 80% or certainty.',
    F('P(H|+) = frac(P(+|H)P(H);P(+|H)P(H)+P(+|L)P(L))','H: tăng trưởng cao; L: nhóm còn lại; +: test tốt; P: xác suất.|H: high growth; L: other firms; +: positive test; P: probability.','Dùng 0,8; 0,3; 0,2; 0,7 theo thứ tự dữ kiện.|Use 0.8, 0.3, 0.2 and 0.7 for the stated probabilities.','H và L phải loại trừ, bao quát và probabilities cùng population.|H and L must be exhaustive, exclusive and from the same population.'));
  add('quantitative','sampling',[
    S('Sai số ngẫu nhiên và bias khác nhau|Random error versus bias','Standard error đo biến động estimator qua các mẫu theo giả định. Bias là lệch hệ thống; tăng n không loại survivorship, selection hoặc bad measurement. Cần xác định population trước sample, không chỉ tải bảng dữ liệu dễ có nhất.|Standard error measures estimator variation under sampling assumptions. Bias is systematic; more observations do not remove selection, survival or measurement errors. Define the target population before choosing convenient data.'),
    S('Confidence interval và phụ thuộc thời gian|Confidence intervals and dependence','Khoảng mean thường dùng estimate cộng/trừ critical value nhân standard error. Công thức s chia căn n cần giả định độc lập hoặc xử lý dependence thích hợp. Monthly returns có autocorrelation không thể coi như cùng số independent observations.|Mean intervals use an estimate plus or minus a critical value times standard error. The usual square-root-n formula needs independence or suitable dependence adjustment; autocorrelated returns are not equivalent to independent observations.'),
    S('Bootstrap không sửa nguồn lệch|Bootstrap does not repair biased data','Resampling mô phỏng sampling variability từ dữ liệu quan sát. Time-series có thể cần block bootstrap để giữ cấu trúc phụ thuộc. Nếu dữ liệu chỉ gồm quỹ còn sống, bootstrap chỉ lặp lại bias; phải sửa universe gốc.|Resampling estimates variability from observed data; time series may need blocks to preserve dependence. Bootstrapping surviving funds merely repeats survival bias. Repair the source universe first.')
  ],'Khoảng mean return có chắc dương?|Is mean return reliably positive?',
    '100 quan sát độc lập, mean 1%/tháng và s=5%. Dùng critical value xấp xỉ 1,96 cho minh họa.|100 independent observations have monthly mean 1% and standard deviation 5%; use an approximate 1.96 critical value.',
    ['SE bằng 0,5%/tháng.|Standard error is 0.5% per month.','Margin xấp xỉ 0,98%; khoảng [0,02%; 1,98%].|The approximate margin is 0.98%, giving [0.02%, 1.98%].','Cận dưới chỉ hơi trên 0; phí, dependence hoặc bias có thể đổi kết luận.|The lower bound barely exceeds zero; costs, dependence or bias can change the conclusion.'],
    'Đây là minh họa theo assumptions, không là xác suất 95% strategy sẽ lời tháng tới.|This is assumption-based inference, not a 95% probability of profit next month.',
    F('SE=frac(s;√n)','s: độ lệch chuẩn mẫu; n: số quan sát độc lập; SE: sai số chuẩn mean.|s: sample standard deviation; n: independent observations; SE: mean standard error.','s=5%, n=100 cho SE=0,5%.|s=5% and n=100 give SE=0.5%.','Với mẫu nhỏ cần critical value và distribution phù hợp; dependence cần điều chỉnh.|Small samples require appropriate critical values and distributions; adjust for dependence.'));
  add('quantitative','regression',[
    S('Null, alternative và sai lầm|Null, alternative and errors','Null thường đặt hệ số bằng một giá trị cụ thể; alternative một phía hoặc hai phía phải xác định trước khi xem kết quả. Type I là bác null đúng; Type II là không bác null sai. Statistical power liên quan xác suất phát hiện effect theo design, không chỉ p-value đã quan sát.|Specify the null and one- or two-sided alternative before results. Type I rejects a true null; Type II fails to reject a false one. Power concerns detection under the design, not simply the observed p-value.'),
    S('OLS và các giả định|OLS and its assumptions','OLS tối thiểu hóa tổng residual bình phương. Interpretation cần correct specification và điều kiện về error; omitted variables và reverse causality gây endogeneity. Heteroskedasticity hoặc autocorrelation ảnh hưởng inference và có thể cần robust methods; không giải quyết bằng tăng R².|OLS minimizes squared residuals. Interpretation depends on specification and errors; omissions and reverse causality create endogeneity. Heteroskedasticity and autocorrelation can require robust inference rather than a higher R².'),
    S('Dự báo ngoài mẫu và extrapolation|Out-of-sample prediction and extrapolation','Model fit trong range lịch sử không bảo đảm chính xác ở regime mới. Prediction interval cho quan sát thường rộng hơn confidence interval của mean. Kiểm tra residual, stability và out-of-sample errors, rồi hỏi effect lớn đủ bù cost không.|Fit within historical ranges does not ensure regime-change accuracy. Observation prediction intervals are generally wider than mean-response intervals. Inspect residuals, stability and test errors, then assess economic significance.')
  ],'Hệ số quảng cáo có đủ cơ sở tăng ngân sách?|Does the advertising slope justify spending?',
    'Slope ước lượng 0,8; SE 0,3; test null bằng 0, hai phía, dùng critical xấp xỉ 1,96.|Estimated slope is 0.8 with SE 0.3; test zero against a two-sided alternative using approximate critical value 1.96.',
    ['Test statistic khoảng 2,667.|The test statistic is about 2.667.','Vượt 1,96 nên bác null theo giả định và mức minh họa.|It exceeds 1.96, so reject under the illustrative assumptions.','Chưa kết luận causal hoặc budget tối ưu; kiểm tra endogeneity, units và incremental margin.|Causality and optimal budget remain unproven; inspect endogeneity, units and incremental margins.'],
    'Statistical significance không phải business recommendation tự động.|Statistical significance is not an automatic business recommendation.',
    F('t=frac(b−b₀;SE(b))','b: slope ước lượng; b₀: giá trị dưới null; SE(b): sai số chuẩn phù hợp.|b: estimated slope; b₀: null value; SE(b): appropriate standard error.','Dùng (0,8−0)/0,3 để tính test statistic.|Use (0.8−0)/0.3 for the statistic.','Critical value phụ thuộc distribution, degrees of freedom và alternative.|The critical value depends on distribution, degrees of freedom and alternative.'));
  add('quantitative','model-governance',[
    S('Data leakage theo thời điểm|Time-based data leakage','Feature phải có sẵn khi lệnh được quyết định, không phải ngày tài chính báo cáo kết thúc. Nếu earnings công bố tháng 3, dùng nó để trade tháng 1 là look-ahead. Dữ liệu revised cần timestamp hoặc point-in-time version.|Features must be available at decision time, not merely associated with an earlier accounting period. Trading in January on earnings released in March is look-ahead. Revised data need timestamps or point-in-time versions.'),
    S('Monte Carlo và uncertainty của tham số|Monte Carlo and parameter uncertainty','Monte Carlo lấy mẫu outcomes từ assumptions. Tăng số lần chạy giảm simulation error nhưng không sửa distribution sai hoặc correlation sai. Tách randomness của outcome khỏi uncertainty về model; stress tail và regime ngoài fitted distribution.|More Monte Carlo paths reduce simulation noise, not misspecified distributions or correlations. Separate outcome randomness from model uncertainty and stress regimes beyond the fitted distribution.'),
    S('Walk-forward và policy dừng|Walk-forward and stopping policy','Train bằng quá khứ, validate, rồi test giai đoạn chưa dùng và cập nhật theo lịch. Ghi số thử tham số để thấy selection risk. Live monitoring cần data quality, drift, cost và drawdown triggers; một breach không tự quyết định nhưng phải có owner xử lý.|Train on past data, validate and test unused periods, updating on a schedule. Record parameter searches to expose selection risk. Monitor data, drift, costs and drawdowns with accountable review triggers.')
  ],'Backtest đẹp nhưng chưa triển khai được|An attractive but untradeable backtest',
    'Strategy gross 14% năm, turnover 600% theo định nghĩa one-way traded notional/NAV; all-in cost 0,5% mỗi notional giao dịch; fee cố định 1%.|A strategy returns 14% gross, with 600% one-way traded-notional/NAV turnover, 0.5% cost per traded notional and 1% fixed fee.',
    ['Trading drag theo giả định là 6 × 0,5%=3%.|Assumed trading drag is 6 × 0.5%=3%.','Net giản lược 10% trước thuế, không phải 13%.|Simplified net return is 10% before tax, not 13%.','Thử cost tăng và capacity; so benchmark cùng risk và fee basis.|Stress costs and capacity and compare a risk- and fee-consistent benchmark.'],
    'Phải định nghĩa turnover để tránh nhân cost sai hoặc tính hai lần.|Define turnover explicitly to avoid misapplying or double-counting costs.');

  add('economics','supply-demand',[
    S('Cân bằng và cú sốc đồng thời|Equilibrium and simultaneous shocks','Giá thị trường là kết quả tương tác cung cầu. Nếu chi phí nguyên liệu tăng và nhu cầu tăng cùng lúc, giá thường chịu áp lực tăng nhưng quantity có thể tăng hoặc giảm tùy độ dịch chuyển. Không dùng quan sát giá tăng để kết luận riêng demand mạnh.|Market price reflects supply and demand together. Rising input costs and demand can both lift prices, while quantity may rise or fall depending on shift size. Higher prices alone do not establish stronger demand.'),
    S('Co giãn chéo và thu nhập|Cross-price and income elasticity','Cross-price elasticity dương thường gợi ý substitutes; âm thường gợi ý complements, giữ yếu tố khác. Income elasticity phân biệt normal và inferior goods theo định nghĩa. Đây là quan hệ ước lượng trong bối cảnh, không nhãn đạo đức hay chất lượng sản phẩm.|Positive cross-price elasticity typically suggests substitutes, negative complements, holding other factors fixed. Income elasticity distinguishes normal and inferior goods. These are contextual estimated relationships, not judgments about product quality.'),
    S('Pass-through và lợi nhuận|Cost pass-through and profit','Khả năng tăng giá theo cost phụ thuộc substitutes, contract resets và sức mua khách. Revenue có thể tăng khi cost inflation nhưng unit margin giảm. Stress đồng thời quantity và contribution thay vì chỉ áp một elasticity lên sales tổng.|Pass-through depends on substitutes, contract resets and customer budgets. Inflation may lift revenue while shrinking unit margins. Stress quantity and contribution together rather than applying one elasticity to total sales.')
  ],'Tăng giá khi nguyên liệu đắt hơn|Pricing after an input-cost shock',
    'Giá cũ 100, biến phí 60, volume 1.000. Giá tăng lên 110, biến phí lên 70, quantity dự kiến giảm 8%; định phí không đổi.|Old price 100, variable cost 60 and volume 1,000. New price 110, cost 70 and expected quantity falls 8%; fixed costs stay constant.',
    ['Revenue cũ 100.000, mới 101.200, tăng 1,2%.|Revenue rises from 100,000 to 101,200, or 1.2%.','Contribution mỗi đơn vị vẫn 40 nhưng tổng giảm từ 40.000 xuống 36.800.|Unit contribution remains 40 but total contribution falls to 36,800 from 40,000.','Profit hoạt động giảm 3.200 nếu không có thay đổi khác; thử giá và cost alternatives.|Operating profit falls 3,200 absent other changes; evaluate pricing and cost alternatives.'],
    'Headline sales tăng chưa chứng minh pass-through đủ bảo vệ profit.|Higher headline sales do not establish adequate profit protection.');
  add('economics','market-structure',[
    S('Price taker và price setter|Price takers and setters','Price taker nhận mức giá thị trường và chọn sản lượng theo marginal cost trong mô hình. Doanh nghiệp có market power đối mặt đường cầu dốc xuống nên marginal revenue có thể thấp hơn price. Profit maximum cần kiểm tra điều kiện và khả năng sản xuất, không chỉ tìm MR=MC máy móc.|A price taker accepts market prices; a price setter faces downward demand and marginal revenue below price. Profit optimization requires the relevant conditions and feasible production, not mechanical MR=MC alone.'),
    S('Oligopoly và phản ứng đối thủ|Oligopoly and rival responses','Tăng giá có thể không giữ nếu rivals giảm giá; đầu tư capacity có thể kích thích overcapacity. Game-theory reasoning cần payoff theo hành động các bên. Không suy hợp tác giá là được phép chỉ vì mô hình cho profit cao; luật cạnh tranh vẫn áp dụng.|Rival pricing and capacity responses affect outcomes. Game-theory reasoning needs payoffs conditional on each side’s actions. A profitable collusive outcome in a model does not establish legal permissibility.'),
    S('Shutdown ngắn hạn khác exit dài hạn|Short-run shutdown versus long-run exit','Fixed costs đã cam kết có thể không tránh được trong kỳ. Nếu revenue bù avoidable cost, tiếp tục tạm thời có thể giảm lỗ. Dài hạn phải bù cả chi phí duy trì và capital cost; không dùng luận điểm short-run để kéo dài mô hình yếu vô hạn.|Unavoidable committed costs may justify temporary operation when avoidable costs are covered. Long-run survival requires maintenance and capital costs too; a short-run argument cannot justify permanent weak economics.')
  ],'Đóng nhà máy ngay hay tiếp tục một quý?|Shut a plant or operate one more quarter?',
    'Revenue quý 500, avoidable operating cost 350, fixed cost 200 đã không thể hủy trong quý. Đóng ngay không có salvage hoặc cost khác.|Quarterly revenue 500, avoidable costs 350 and unavoidable fixed costs 200. Closing has no salvage or other costs.',
    ['Tiếp tục lỗ kế toán 50 theo mô hình.|Continuing produces an accounting loss of 50.','Đóng vẫn tốn fixed 200, nên kết quả xấu hơn 150.|Closing still costs 200, worse by 150.','Tiếp tục một quý có thể hợp lý; đánh giá exit dài hạn riêng trước khi renew fixed commitments.|Continuing for the quarter can be sensible; separately evaluate exit before renewing commitments.'],
    'Phân loại chi phí tránh được mới là trọng tâm của quyết định hiện tại.|Avoidability, not the accounting label alone, drives the current decision.');
  add('economics','business-cycle',[
    S('Output gap và cấu trúc ngành|Output gaps and industry structure','Mức GDP hiện tại khác tốc độ GDP growth; growth chậm vẫn có thể là expansion nếu dương. Output gap so activity với potential, vốn khó ước lượng. Ngành durable thường nhạy hoãn mua; nhu yếu phẩm có thể ổn định hơn nhưng margin vẫn chịu input cost.|GDP level differs from growth; slower positive growth can still be expansion. Output gaps compare activity with uncertain potential. Durable goods are postponable; essentials may be steadier but remain exposed to cost pressures.'),
    S('Tồn kho, credit và employment|Inventory, credit and employment','Doanh nghiệp dự báo sai có thể tích tồn kho trước downturn, rồi cắt sản xuất lớn hơn mức giảm tiêu dùng. Credit tightening làm khuếch đại; employment có thể phản ứng chậm. Kết hợp indicators theo cơ chế thay vì gán phase từ một headline.|Forecast errors can build inventory before downturns and amplify production cuts. Tightening credit compounds the effect while employment may lag. Combine indicators through an economic mechanism rather than one headline.'),
    S('Normalize earnings theo chu kỳ|Normalize across the cycle','Chọn margin và utilization bình thường có căn cứ, không tự lấy trung bình nếu ngành đã đổi cấu trúc. Balance-sheet resilience quan trọng khi profit thấp: debt maturity, inventory liquidation và cash burn quyết định khả năng sống qua trough.|Normalize margins and utilization with evidence rather than averaging across structural breaks. Debt maturities, inventory liquidation and cash burn determine resilience during troughs.')
  ],'Cổ phiếu cyclical nhìn rất rẻ|A cyclical stock looks cheap',
    'Price 60, EPS peak 10; normalized EPS giả định 4. Công ty còn debt maturity lớn khi công suất đang đầy.|Price 60, peak EPS 10 and assumed normalized EPS 4, with a large debt maturity ahead.',
    ['Peak P/E chỉ 6 lần.|Peak P/E is only six.','Normalized P/E là 15 lần; mức rẻ phụ thuộc earnings base.|Normalized P/E is fifteen, changing the cheapness claim.','Stress refinancing và margin giảm, không chỉ chọn multiple 6.|Stress refinancing and margins rather than relying on six-times peak earnings.'],
    'Cần phân biệt earnings đang cao do phase với lợi thế bền vững.|Separate cyclical peak earnings from durable advantage.');
  add('economics','policy',[
    S('Policy rate truyền tới doanh nghiệp|Policy-rate transmission','Policy rate ảnh hưởng funding, lending, valuation và currency, nhưng lãi khoản vay fixed cũ có thể chưa đổi. Reset dates, pass-through và credit availability quyết định tác động. Một đợt cắt rate để phản ứng suy yếu có thể đi cùng earnings xấu hơn.|Policy rates affect funding, credit, valuations and currencies, but existing fixed debt may not reset immediately. Reset dates and access determine impact; cuts responding to weakness can coincide with worse earnings.'),
    S('Demand-pull và supply shock|Demand and supply inflation','Lạm phát do demand mạnh khác do input shortage. Thắt chặt có thể giảm cầu nhưng không tự tạo thêm dầu hoặc chip ngay. Đánh giá output, real income và margin cùng inflation; không dùng một policy response cố định cho mọi shock.|Demand-led inflation differs from input shortages. Tightening may reduce demand without immediately supplying oil or chips. Evaluate output, real income and margins alongside inflation.'),
    S('Fiscal multiplier phụ thuộc bối cảnh|Fiscal effects depend on context','Chi tiêu tăng có thể nâng demand nhưng bị bù bởi thuế tương lai, crowding-out, imports và năng lực supply. Deficit không luôn tạo cùng inflation hoặc bond yield. Xem funding, currency regime và policy credibility trong scenario.|Spending can lift demand but interact with future taxes, crowding out, imports and supply capacity. Deficits do not always produce identical inflation or yields; consider funding, currency regime and credibility.')
  ],'Lãi giảm mà chi phí vay tăng?|Rates fall but borrowing cost rises?',
    'Base rate giảm 1 điểm %, credit spread công ty tăng từ 2% lên 4%; toàn khoản vay floating reset ngay.|The base rate falls one percentage point while the firm’s spread rises from 2% to 4%; all floating debt resets immediately.',
    ['Rate vay là base cộng spread theo giả định.|Borrowing rate equals base plus spread under the terms.','Giảm 1 nhưng tăng spread 2 làm all-in rate tăng 1 điểm %.|A one-point base cut and two-point spread increase raise the total rate one point.','Dự báo interest từ debt terms và credit outlook, không từ central-bank headline riêng.|Forecast interest from debt terms and credit outlook, not the policy headline alone.'],
    'Policy easing không bảo đảm mọi borrower được funding rẻ hơn.|Policy easing does not guarantee cheaper funding for every borrower.');
  add('economics','fx',[
    S('Transaction, translation và economic exposure|Three currency exposures','Transaction exposure gắn khoản thu/trả cụ thể; translation là chuyển báo cáo sang reporting currency; economic exposure là sức cạnh tranh và future cash. Một accounting FX gain chưa chắc có cash nhận, và hedge một invoice không xóa exposure dài hạn.|Transactions are specific receipts/payments, translation converts reports, and economic exposure concerns competitiveness and future cash. Accounting FX gains need not be cash receipts; hedging an invoice does not remove long-term exposure.'),
    S('Forward pricing không phải forecast|Forward pricing is not a forecast','Với quote domestic/foreign, covered parity dùng lãi domestic ở tử và foreign ở mẫu theo cùng kỳ. Điều này nối cách tài trợ và hedge, không khẳng định đồng tiền sẽ di chuyển đúng forward. Kiểm tra collateral và basis khi áp dụng thực tế.|For domestic-per-foreign quotes, covered parity puts the domestic rate above the foreign rate for the same period. It connects funding and hedging rather than predicting spot. Collateral and basis matter in practice.'),
    S('Hedge theo net cash và thời gian|Hedge net cash and timing','Doanh thu và nợ cùng ngoại tệ có thể bù nhau nhưng chỉ khi timing và amount phù hợp. Exporter vẫn có cost currency khác và price competition. Tách natural hedge đã có trước khi thêm derivative để tránh overhedge.|Foreign revenue and debt offset only when amount and timing align. Exporters still face cost currencies and pricing competition. Account for natural hedges before adding derivatives.')
  ],'Hóa đơn USD và natural hedge|A USD invoice and natural hedge',
    'Trong ba tháng công ty phải trả USD 1 triệu và chắc chắn thu USD 400.000 cùng ngày; bỏ risk thu tiền và phí.|In three months the firm owes USD 1 million and will certainly receive USD 400,000 on the same day; ignore collection risk and fees.',
    ['Net payment là USD 600.000.|The net payment is USD 600,000.','Hedge toàn USD 1 triệu sẽ thừa USD 400.000 nếu không exposure khác.|Hedging the full million overhedges by USD 400,000 without other exposure.','Xác nhận timing, certainty và objective rồi chọn hedge net phù hợp.|Confirm timing, certainty and objective before hedging the net exposure.'],
    'Net exposure phải xuất phát từ cash schedule chứ không chỉ tổng nợ ngoại tệ.|Net exposure comes from the cash schedule, not just total foreign debt.',
    F('F=S×frac(1+i_d;1+i_f)','F: forward domestic/foreign một kỳ; S: spot cùng quote; i_d, i_f: lãi hiệu dụng domestic và foreign cùng kỳ.|F: one-period domestic/foreign forward; S: matching spot quote; i_d and i_f: same-period effective domestic and foreign rates.','Spot 25.000, lãi domestic 4%, foreign 2% cho forward khoảng 25.490,196 theo mô hình.|Spot 25,000 with 4% domestic and 2% foreign rates implies about 25,490.196.','Giả định covered no-arbitrage, không phí, basis hoặc constraints đáng kể.|Assume covered no-arbitrage without material costs, basis or constraints.'));

  add('fsa','framework',[
    S('Câu hỏi creditor và shareholder|Creditor and shareholder questions','Creditor ưu tiên capacity trả interest/principal và recovery; shareholder quan tâm residual cash, growth và giá trả. Cùng một buyback có thể tăng EPS nhưng làm liquidity và credit yếu hơn. Đặt quyết định trước rồi chọn ratios tương ứng.|Creditors prioritize debt service and recovery; shareholders residual cash, growth and price. A buyback may raise EPS while weakening liquidity and credit. Define the decision before selecting ratios.'),
    S('Common-size, trend và comparability|Common-size, trends and comparability','Common-size income statement chia cho revenue, balance sheet thường chia total assets. Trend chỉ đúng khi periods và policies so được. M&A, FX, reclassification và fiscal-year lengths có thể tạo growth không do operations; đọc bridge và notes.|Common-size statements scale income by revenue and balance-sheet items by assets. Trends require comparable periods and policies. M&A, FX, reclassification and year length can mimic operating growth.'),
    S('DuPont và mẫu số bình quân|DuPont and average balances','Nối net margin, turnover và leverage để biết ROE tăng từ đâu. Nếu equity nhỏ do buyback hoặc lỗ, ROE có thể phình không phản ánh năng lực tốt. Average assets/equity thường phù hợp flow cả năm; acquisitions giữa kỳ cần đánh giá thêm.|Connect margin, turnover and leverage to identify ROE sources. Buybacks or losses can shrink equity and inflate ROE. Average balances better match annual flows, with midyear acquisitions requiring care.')
  ],'ROE tăng vì kinh doanh hay leverage?|Did operations or leverage raise ROE?',
    'Năm A: margin 8%, turnover 1,25, equity multiplier 2. Năm B: margin 8%, turnover 1,25, multiplier 3.|Year A has 8% margin, 1.25 turnover and multiplier 2; year B keeps margin and turnover but raises multiplier to 3.',
    ['ROE A là 20%.|Year A ROE is 20%.','ROE B là 30%, nhưng operating margin và turnover chưa cải thiện.|Year B ROE is 30%, without improved operating margin or turnover.','Kiểm tra debt service, buyback và equity base trước khi khen quản trị vận hành.|Review debt service, buybacks and equity before crediting operating performance.'],
    'Phân rã chỉ ra nguồn tăng, còn quyết định cần đánh giá risk và sustainability.|Decomposition identifies the source; judgment needs risk and sustainability too.');
  add('fsa','revenue-tax',[
    S('Principal-agent và gross/net|Principal-agent and gross/net','Xác định doanh nghiệp kiểm soát hàng hoặc dịch vụ trước khi chuyển cho khách hay chỉ sắp xếp giao dịch. Presentation gross/net có thể làm revenue và gross margin thay đổi lớn dù fee economics tương tự. Không suy vai trò chỉ từ tên “platform”.|Determine whether the firm controls goods/services before transfer or merely arranges the transaction. Gross/net reporting can alter revenue and margins without similar economic changes. The word platform does not settle the role.'),
    S('Tax base, temporary và permanent differences|Tax bases and differences','Temporary difference có thể đảo ngược và tạo deferred tax theo rules; permanent difference không tự tạo deferred tax. DTL không phải mọi loại tax debt và DTA không phải cash chắc chắn thu. Đánh giá thời điểm reversal và khả năng có taxable income phù hợp.|Temporary differences can reverse and create deferred tax; permanent differences generally do not. DTLs are not all tax liabilities and DTAs are not certain cash. Assess reversals and suitable taxable income.'),
    S('Reconciliation từ statutory tới effective|Statutory-to-effective tax reconciliation','So expense với pretax income rồi giải thích tax rates nhiều nước, permanent items và one-offs. Tax payable khác tax expense do timing. Forecast rate dựa cơ chế bền vững, không chỉ lấy một năm có tax credit bất thường.|Reconcile expense to pretax income using jurisdictions, permanent items and one-offs. Payable differs from expense through timing. Forecast sustainable mechanisms rather than an unusual credit year.')
  ],'Khấu hao thuế nhanh tạo DTL|Accelerated tax depreciation creates a DTL',
    'Máy carrying amount 80, tax base 60; thuế suất áp dụng khi đảo ngược 25%; giả sử taxable temporary difference được ghi nhận đầy đủ.|An asset carries at 80 with tax base 60; reversal tax rate is 25%; assume full recognition of the taxable temporary difference.',
    ['Chênh lệch tạm thời chịu thuế là 20.|The taxable temporary difference is 20.','DTL tương ứng 5.|The resulting DTL is 5.','Tax tiết kiệm hiện tại từ khấu hao nhanh không phải lợi ích vĩnh viễn; xem reversal trong forecast.|The present tax saving is timing-related, not necessarily permanent; model reversal.'],
    'Cần dùng tax base và rate phù hợp, không lấy chênh tax cash với expense rồi gọi tất cả là DTL.|Use the appropriate tax base and rate rather than labeling every cash-tax gap a DTL.',
    F('DTL=(CA−TB)×T','CA: carrying amount của asset; TB: tax base; T: rate khi reversal; ví dụ taxable difference.|CA: asset carrying amount; TB: tax base; T: reversal rate; this example concerns a taxable difference.','Thay 80, 60 và 25% để được 5.|Use 80, 60 and 25% to obtain 5.','Nhận diện loại chênh lệch và exceptions theo chuẩn trước khi áp dụng.|Identify difference type and recognition exceptions under the applicable standard.'));
  add('fsa','assets-debt',[
    S('Inventory write-down và cash|Inventory write-downs and cash','Write-down giảm carrying amount khi điều kiện chuẩn yêu cầu, không chi thêm cash ngay. Nó có thể báo inventory đã mua khó bán; forecast phải xét mất gross margin và khả năng thay stock. Khi so IFRS/GAAP, rules reversal có thể khác.|A write-down reduces carrying value without an immediate new payment. It may reveal difficulty selling purchased stock; forecast margins and replacement needs. Reversal rules can differ across frameworks.'),
    S('Lease và comparability leverage|Leases and leverage comparability','Lease tạo quyền dùng và nghĩa vụ theo điều kiện ghi nhận; treatment expense và cash classification khác theo chuẩn và loại lease. Khi chuẩn hóa debt/EBITDA, phải điều chỉnh cả numerator và denominator nhất quán; không chỉ cộng lease debt rồi giữ expense basis tùy ý.|Lease recognition creates use rights and obligations under applicable conditions. Expense and cash classification differ by framework and type. Lease-adjusted debt/EBITDA needs consistent changes to both measures.'),
    S('Impairment và recoverability|Impairment and recoverability','Tài sản hiệu quả thấp có thể cần impairment, nhưng phép đo không chỉ nhìn giá cổ phiếu giảm. Xác định asset hoặc cash-generating unit, forecasts, discount rate và rules áp dụng. Dự báo quá lạc quan trì hoãn loss; write-off hôm nay không tự cải thiện economics ngày mai.|Weak assets may require impairment, using the appropriate asset/group and recovery rules rather than share prices alone. Optimistic forecasts can defer losses; write-offs do not by themselves improve future economics.')
  ],'Giá trị ghi sổ và collateral thực|Book value versus real collateral',
    'Máy book 100, bán cưỡng bức dự kiến 65, chi phí bán 5; bond có collateral là máy và claim 80. Bỏ mọi priority khác.|A pledged machine carries at 100, forced-sale proceeds are estimated at 65 and sale cost 5; secured claim 80, no other priorities.',
    ['Net collateral proceeds chỉ 60.|Net collateral proceeds are 60.','Recovery từ pool này 75% claim, shortfall 20 theo giả định.|This pool covers 75% of the claim, leaving a 20 shortfall.','Điều tra quyền phần shortfall ở pool khác và law; không coi book 100 là đủ bảo đảm.|Investigate deficiency rights and law instead of treating book 100 as coverage.'],
    'Accounting carrying value và enforcement recovery trả lời hai câu hỏi khác nhau.|Carrying value and enforcement recovery answer different questions.');
  add('fsa','cash-quality',[
    S('Bridge accruals qua nhiều kỳ|Bridge accruals across periods','Một kỳ CFO thấp có thể do seasonality hoặc growth; nhiều kỳ profit vượt cash cần cơ chế rõ. So receivables aging, returns, inventory và tax payments. Tìm reversal dự kiến và xem kỳ sau có thực sự đảo ngược, thay vì chấp nhận giải thích “timing” mãi.|One weak cash period may reflect seasonality or growth; persistent gaps need explanation. Inspect aging, returns, stock and tax payments. Check whether promised timing reversals actually occur.'),
    S('Factoring và supplier finance|Factoring and supplier finance','Bán phải thu có thể đẩy cash về sớm nhưng có phí và có thể giữ risk qua recourse. Supplier finance có thể thay đổi funding profile dù payable còn nhìn như operating. Đọc notes và chuẩn hóa để so capacity tài trợ thực.|Factoring accelerates cash but has fees and possible recourse. Supplier finance can change funding even when amounts resemble operating payables. Read disclosures and normalize financing capacity.'),
    S('Recurring cash khác cash từ tái cơ cấu|Recurring cash versus restructuring cash','Thanh lý nhà máy hay sale-and-leaseback có thể tăng cash hiện tại nhưng tạo rent và mất tài sản. Không cộng proceeds này vào operating earning power vô hạn. Model cash sau maintenance capex và obligations mới.|Disposals and sale-leasebacks can raise cash while adding rent or removing assets. Do not project proceeds as recurring operating power. Model maintenance capex and new obligations.')
  ],'CFO tốt nhờ thu sớm năm sau|Strong CFO borrowed from next year',
    'CFO 120 gồm 50 cash từ factoring mới một lần; fee đã nằm trong profit. Maintenance capex 60, không khoản khác.|CFO 120 includes a new one-time 50 factoring inflow; fees are already in profit. Maintenance capex is 60, with no other items.',
    ['Reported CFO trừ capex là 60.|Reported CFO less capex is 60.','Nếu loại riêng timing inflow 50, proxy normalized còn 10.|Removing the 50 timing inflow gives a normalized proxy of 10.','Không trừ fee lần hai; đánh giá future collections, recourse và funding dependence.|Do not deduct the fee twice; assess future collections, recourse and dependence.'],
    'Normalization cần rõ khoản nào đổi và không giả làm forecast đầy đủ.|State precisely what changes; a normalization proxy is not a complete forecast.');
  add('fsa','forecast',[
    S('Integrated forecast từ volume đến funding|Integrated volume-to-funding forecasts','Revenue drives cost, receivable và inventory; capacity drives capex; debt drives interest và tax. Forecast một dòng profit mà không đóng balance sheet có thể che funding gap. Dùng cash minimum và funding policy để giải vòng lặp phù hợp.|Revenue drives costs and working capital; capacity drives capex; debt drives interest and tax. A profit-only forecast hides funding gaps. Specify minimum cash and financing policy to resolve interactions.'),
    S('Stable growth cần reinvestment|Stable growth needs reinvestment','Trong mô hình ổn định, growth liên hệ return on incremental capital và reinvestment rate. Nếu giả growth dài hạn mà không có capex hoặc working capital hỗ trợ, terminal cash có thể bị thổi phồng. Tách assets có khả năng scale nhẹ vốn nhưng vẫn kiểm tra capacity.|Stable growth depends on incremental capital returns and reinvestment. Growth without supporting capex or working capital can inflate terminal cash. Capital-light scaling needs evidence, not an automatic exemption.'),
    S('Scenarios phải giữ quan hệ kinh tế|Keep scenarios economically coherent','Bear case không chỉ giảm revenue mà giữ tất cả margin, DSO và funding như base. Weak demand có thể làm stock dư, payment chậm và spread tăng. Xác định assumptions đồng biến để thấy liquidity tail chứ không chỉ valuation sensitivity.|A bear case should not reduce sales while automatically retaining base margins, collections and funding. Weak demand may raise stock, delays and spreads. Model linked assumptions to reveal liquidity tails.')
  ],'Doanh thu tăng nhưng cần vay|Growth requiring new debt',
    'Revenue tăng từ 100 lên 130; receivable 20% sales, inventory 15%, payable 10%. Incremental operating cash trước working capital là 8; capex tăng thêm 5.|Sales rise from 100 to 130; receivables are 20%, inventory 15% and payables 10% of sales. Incremental operating cash before working capital is 8; incremental capex is 5.',
    ['Net operating working capital bằng 25% sales, tăng từ 25 lên 32,5.|Operating net working capital is 25% of sales and rises from 25 to 32.5.','Growth dùng thêm 7,5 working capital.|Growth consumes 7.5 in working capital.','Incremental cash sau capex là 8−7,5−5=−4,5; cần nguồn cho gap này.|Incremental cash after capex is −4.5, requiring funding.'],
    'Forecast growth phải nối được tới nguồn vốn, kể cả khi profit tăng.|Growth forecasts must reconcile to funding even when profit rises.');

  add('corporate-finance','governance',[
    S('Quyền quyết định đi cùng vốn|Decision rights and capital','Capital allocation gồm tái đầu tư, M&A, debt repayment, dividends và buybacks. Các phương án tranh nhau cùng cash. Board cần đánh giá opportunity cost và horizon; giữ cash cũng có thể có giá trị khi có distress hoặc cơ hội, không mặc nhiên là lười đầu tư.|Reinvestment, acquisitions, repayment, dividends and buybacks compete for cash. Boards must assess opportunity costs and horizons. Cash can have option or resilience value rather than automatically signal poor investment effort.'),
    S('Agency cost và incentive|Agency costs and incentives','Manager có thể thích quy mô, chủ lớn có thể chuyển lợi ích qua related parties, cổ đông equity có thể thích gamble khi debt lớn. Không giả tất cả stakeholders cùng mục tiêu. Controls và compensation nên nối quyết định với return trên capital, risk và thời gian.|Managers may favor scale, controllers related benefits and leveraged shareholders risk-taking. Stakeholder objectives differ. Controls and compensation should connect decisions to capital returns, risk and time.'),
    S('Đánh giá ESG qua cơ chế cash|Assess sustainability through cash mechanisms','Rủi ro môi trường, lao động hoặc governance có thể tác động license, demand, cost và discount rate. Nêu cơ chế cụ thể và evidence, tránh thêm premium hoặc discount tùy ý. Cùng rủi ro không nên bị phạt lặp trong cash và rate mà không giải thích.|Environmental, labor and governance risks may affect licenses, demand, costs and rates. State mechanisms and evidence instead of arbitrary discounts. Explain rather than double-count the same risk in cash and discounting.')
  ],'Mở rộng hay trả vốn?|Expand or return capital?',
    'Công ty có cash dư 100; dự án A chi 100, NPV −8 theo suất phù hợp. CEO được thưởng theo asset growth.|The firm has 100 surplus cash; project A costs 100 and has NPV −8 at a suitable rate. The CEO is rewarded for asset growth.',
    ['So dự án với alternatives, không coi cash sẵn có là capital miễn phí.|Compare alternatives rather than treating cash as free capital.','NPV âm là dấu hiệu không đạt required return; kiểm tra assumptions và strategic options có thật.|Negative NPV signals insufficient return; verify assumptions and genuine strategic options.','Xem incentive khuyến khích đầu tư yếu và cân nhắc trả vốn hoặc giữ option có căn cứ.|Review incentives and consider distributions or justified option value.'],
    'Thưởng theo scale cần kiểm soát để không biến growth thành mục tiêu thay value.|Scale-based incentives need controls so growth does not displace value.');
  add('corporate-finance','working-capital',[
    S('Conservative và aggressive funding|Conservative and aggressive funding','Dùng debt ngắn cho assets dài có thể rẻ lúc đầu nhưng tạo refinancing gap. Conservative policy giữ liquidity cao hơn nhưng có carrying cost. Chọn theo cash volatility, committed lines và access khi stress; không chỉ lãi vay hiện tại.|Short funding of long assets may look cheap but creates refinancing gaps. Conservative liquidity has carrying costs. Choose based on cash volatility, committed facilities and stressed access, not current borrowing rates alone.'),
    S('Credit policy theo incremental economics|Credit policy as an incremental decision','Nới credit có thể tăng sales nhưng tăng bad debts, receivable và funding cost. Tính incremental contribution sau các tác động này. Phân biệt sales shift từ kỳ khác với demand tăng thật; payment delay của khách cũ cũng quan trọng.|Looser credit can increase sales, bad debts, receivables and funding costs. Calculate incremental contribution after all effects. Distinguish timing shifts from new demand and include delays by existing customers.'),
    S('Trade discount như một nguồn vay|Forgone discounts as borrowing','Bỏ discount để trả muộn là chi phí tài trợ trên số tiền được hoãn, với thời gian ngắn cụ thể. Annualized simple rate là phép so sánh, không chắc bạn có thể lặp điều kiện cả năm. Kiểm tra ability vay thay thế và supplier relationship.|Forgoing a discount finances the delayed amount for a defined period. A simple annualized rate is a comparison, not a guarantee of repeatable annual terms. Assess available funding and supplier relationships.')
  ],'Có nên bỏ chiết khấu thanh toán?|Should the discount be forgone?',
    'Hóa đơn 100 theo 2/10 net 30. Có thể vay 20 ngày với simple annual rate 12%, dùng 365 ngày, không phí.|Invoice 100 has 2/10 net 30 terms; a 20-day loan is available at 12% simple annual interest on a 365-day basis, without fees.',
    ['Trả ngày 10 chỉ tốn 98, cần vay 98.|Paying on day ten costs 98 and requires borrowing 98.','Interest 20 ngày khoảng 0,644; tổng cost tương đương 98,644.|Twenty-day interest is about 0.644, for total cost about 98.644.','Thấp hơn trả 100 ngày 30 khoảng 1,356; xác nhận terms và ability vay.|This saves about 1.356 versus paying 100 on day thirty, subject to terms and availability.'],
    'Đừng so “discount 2%” trực tiếp với “lãi 12% năm” khi hai kỳ khác nhau.|Do not compare a short-period 2% discount directly with 12% annual interest.');
  add('corporate-finance','npv',[
    S('Cash liên quan gồm cannibalization|Relevant cash includes cannibalization','Dự án mới có thể lấy sales từ sản phẩm cũ, dùng đất có thể bán hoặc cần working capital thu hồi cuối đời. Những khoản này là incremental economics dù không xuất hiện trên hóa đơn máy mới. Sunk study cost khác chi phí cơ hội của đất đang sở hữu.|New projects can cannibalize products, use saleable land and tie up recoverable working capital. These are relevant economics even without new equipment invoices. Sunk studies differ from owned-land opportunity costs.'),
    S('Real options và flexibility|Real options and flexibility','Quyền trì hoãn, mở rộng hoặc bỏ dự án có giá trị khi uncertainty và flexibility đáng kể. Không cộng một “strategic premium” không định lượng để cứu mọi NPV âm. Xây tree với thời điểm, payoffs và khả năng thực hiện option.|Delay, expansion and abandonment can add value under uncertainty. Do not add an unquantified strategic premium to rescue every negative NPV. Model timing, payoffs and feasible options.'),
    S('IRR và mutually exclusive projects|IRR and exclusive projects','Dự án nhỏ IRR cao có thể tạo ít value hơn dự án lớn. Khác timing cũng gây ranking conflict; cash đổi dấu nhiều lần có thể có nhiều IRR. Với cùng mục tiêu và vốn không ràng buộc, phân tích incremental NPV trên discount rate phù hợp.|A small high-IRR project can create less value than a large one. Timing and multiple sign changes cause conflicts or multiple IRRs. With suitable assumptions, compare incremental NPV.')
  ],'Working capital không được bỏ quên|Do not omit working capital',
    'Máy cần 100 và working capital 20 ở t=0; operating cash sau thuế 70 cuối năm 1, 70 cuối năm 2; thu hồi WC 20 cuối năm 2; r=10%.|Equipment costs 100 and working capital 20 now. After-tax operating cash is 70 in years one and two; recover working capital 20 in year two; rate 10%.',
    ['Initial outflow 120.|Initial outflow is 120.','PV inflows là 70/1,1 + 90/1,1², khoảng 138,017.|PV inflows are about 138.017.','NPV khoảng 18,017; kiểm tra salvage và WC recoverability, không cộng thêm financing cash vào project.|NPV is about 18.017; check salvage and recoverability without adding financing proceeds to the project.'],
    'Funding được xử lý nhất quán với discount rate; tiền vay không làm NPV dự án tăng miễn phí.|Treat financing consistently with the discount rate; borrowing is not free project value.');
  add('corporate-finance','wacc',[
    S('Cost of equity không phải dividend yield|Equity cost is not dividend yield','Nhà đầu tư đòi return tổng gồm price change và distributions phù hợp risk. CAPM là một cách estimate; inputs beta và premium có uncertainty. Một công ty không trả dividend vẫn có equity cost vì chủ bỏ cơ hội đầu tư khác.|Required equity return includes price change and distributions for risk. CAPM is one estimation approach with uncertain beta and premiums. No-dividend firms still use capital with an opportunity cost.'),
    S('Tax shield và distress|Tax shields and distress','Debt interest deductions phụ thuộc luật và taxable capacity. Khi debt tăng, equity và debt costs có thể cùng tăng. Capital structure target nên phản ánh rating, flexibility và refinancing; không cố giữ cost từng nguồn hằng số khi thay leverage mạnh.|Interest deductions depend on law and taxable capacity. More leverage can raise both capital costs. Targets should reflect credit, flexibility and refinancing rather than holding source costs constant at any leverage.'),
    S('Matching cash, currency và risk|Match cash, currency and risk','FCFF dùng WACC phù hợp assets; FCFE dùng equity cost. Một project ngoại tệ hoặc business risk khác cần inputs khác. Nếu dùng target market weights, ghi rõ assumptions và treatment cash/nonoperating assets trong valuation bridge.|FCFF uses an asset-appropriate WACC and FCFE an equity cost. Different currencies or business risks need different inputs. Explain market weights and nonoperating assets in the valuation bridge.')
  ],'WACC thấp giả vì dùng book weights|A misleading WACC from book weights',
    'Market equity 300, debt market 100, equity cost 12%, pretax debt cost 6%, tax 25%; tax shield dùng được.|Market equity 300, debt 100, equity cost 12%, pretax debt cost 6%, tax 25%, with usable deductions.',
    ['Market weights là 75% equity và 25% debt.|Market weights are 75% equity and 25% debt.','After-tax debt cost 4,5%.|After-tax debt cost is 4.5%.','WACC 10,125%; dùng book equity 100 thay market 300 sẽ tạo weights khác không có căn cứ cho câu hỏi này.|WACC is 10.125%; substituting book equity 100 creates inappropriate weights for this question.'],
    'Input và claim phải nhất quán; một số thấp hơn không tự tốt hơn.|Consistency matters more than obtaining a lower number.',
    F('WACC=w_e r_e+w_d r_d(1−T)','w_e,w_d: market weights tổng 1; r_e: equity cost; r_d: pretax debt cost; T: marginal tax rate phù hợp.|w_e,w_d: market weights summing to one; r_e: equity cost; r_d: pretax debt cost; T: relevant marginal tax rate.','0,75 × 12% + 0,25 × 6% × 0,75 = 10,125%.|The case gives 10.125%.','Giả định tax shield sử dụng được và risk/leverage phù hợp.|Assume usable deductions and appropriate risk and leverage.'));
  add('corporate-finance','restructuring',[
    S('Synergy phải sau cost và tax|Synergy after costs and taxes','Revenue synergy có thể cần marketing và vốn lưu động; cost savings có thể cần severance và capex. Forecast timing chậm làm PV giảm. Không cộng EBITDA synergy như cash flow và bỏ taxes, integration hay churn khách.|Revenue synergies may require marketing and working capital; cost savings can require severance and capex. Delays reduce PV. EBITDA synergies are not automatically cash without tax, integration and retention effects.'),
    S('Ai hưởng premium và synergy?|Who receives premium and synergy?','Target owners thường nhận premium qua price; buyer chỉ giữ value vượt consideration và costs. Mua bằng shares chuyển một phần synergy cho target và làm dilution quyền sở hữu. EPS accretion khác buyer NPV.|Target holders capture premiums; buyers retain only value beyond price and costs. Share consideration transfers some synergy and ownership. EPS accretion differs from buyer NPV.'),
    S('Divest, spin-off và buyback|Divestitures, spin-offs and buybacks','Bán mảng tạo cash nhưng mất future flows; spin-off phân phối quyền sở hữu khác bán lấy cash; buyback thay đổi shares và balance sheet. So cấu trúc mới với status quo sau taxes, transaction costs và mất diversification benefits.|A sale raises cash but removes future flows; a spin-off distributes ownership rather than sale cash; buybacks change shares and the balance sheet. Compare after tax, cost and lost benefits.')
  ],'Synergy không đủ trả premium|Synergies do not cover the premium',
    'Standalone target 200, giá trả 250, PV synergy sau thuế 70, integration PV 30; không claim khác.|Target standalone value 200, price 250, after-tax synergy PV 70 and integration PV 30; no other claims.',
    ['Net synergy 40.|Net synergy is 40.','Buyer nhận value 240 nhưng trả 250, NPV −10.|Buyer value is 240 against price 250: NPV −10.','Muốn deal tạo value phải giảm price hoặc chứng minh additional net benefits có căn cứ.|Value creation requires a lower price or evidenced additional net benefits.'],
    'Một deal EPS-accretive vẫn có thể chuyển hết value cho người bán.|An EPS-accretive deal can still transfer all value to sellers.');

  add('equity','markets-indexes',[
    S('Bid–ask, depth và loại lệnh|Spreads, depth and order types','Bid là giá mua sẵn, ask là giá bán sẵn; market buy thường chạm ask nhưng order lớn có thể ăn nhiều levels. Spread chỉ một phần execution cost. Stop order kích hoạt lệnh theo terms, không đảm bảo giá stop nếu market gap.|Market buys generally reach the ask but large orders consume depth. Spreads are only part of execution costs. A stop triggers an order under its terms rather than guaranteeing the stop price through gaps.'),
    S('Market efficiency không nghĩa giá luôn đúng|Efficiency does not mean perfect prices','Weak, semi-strong và strong forms mô tả tập thông tin phản ánh theo lý thuyết. Outperformance sau fees cần so risk và luck; phát hiện anomaly lịch sử có thể do data mining. Một correction sau tin không tự chứng minh market trước đó phi lý.|Efficiency forms concern information sets. After-fee outperformance requires risk and luck assessment; historical anomalies can be mined. Price changes after new information do not alone prove earlier irrationality.'),
    S('Index construction tạo concentration|Index construction creates exposures','Cap-weight index tập trung hơn khi mega-caps tăng; equal-weight thường cần rebalance và chịu turnover. Float, corporate actions và reconstitution ảnh hưởng return. Price index bỏ dividends khác total return index; dùng cùng basis khi đánh giá fund.|Cap weighting concentrates as large firms rise; equal weighting requires turnover. Float and reconstitution matter. Price indexes exclude dividends unlike total-return indexes, so benchmark bases must match.')
  ],'Order nhỏ trên chart nhưng lớn so depth|A small order relative to weak depth',
    'Ask có 100 shares ở 10,00 và 400 ở 10,10; bạn market-buy 500, bỏ fees.|The ask has 100 shares at 10.00 and 400 at 10.10; buy 500 at market, ignoring fees.',
    ['Trả 1.000 cho 100 đầu và 4.040 cho phần còn lại.|Pay 1,000 for the first block and 4,040 for the rest.','Average execution 10,08, không phải quoted best ask 10,00.|Average execution is 10.08 rather than best ask 10.00.','Đánh giá urgency, depth và limit alternatives; limit có risk không khớp.|Consider urgency, depth and limits, which may not fill.'],
    'Quoted price không bảo đảm cả order thực hiện tại đó.|A displayed price does not guarantee the whole order at that price.');
  add('equity','industry-moat',[
    S('Industry boundaries và profit pool|Boundaries and profit pools','Tách customer problem khỏi nhãn sector. Taxi và nền tảng gọi xe có thể cạnh tranh cùng nhu cầu; retailer online và offline có thể chia profit pool. Xác định ai capture value giữa producer, distributor và platform trước khi so market share.|Customer needs can cross sector labels. Ride platforms compete with taxis; online and offline retail may share a profit pool. Locate value capture across producers, distributors and platforms before comparing share.'),
    S('Pricing power phải kiểm tra quantity|Test pricing power with quantity','Một price rise thành công cần retention, mix và cost context. Revenue tăng có thể do inflation toàn ngành chứ không riêng moat. So peers, contract cycles và churn sau renewals; đừng kết luận từ một quarter chưa reset hợp đồng.|Successful price increases need retention, mix and cost context. Industry inflation can lift revenue without a unique moat. Compare peers, contract resets and post-renewal churn rather than one premature quarter.'),
    S('Moat fade và reinvestment runway|Moat fade and reinvestment runway','Excess ROIC thu hút cạnh tranh trừ khi rào cản bảo vệ. Forecast fade về competitive economics có cơ chế; xem regulatory và technology disruption. Quy mô thị trường còn lại quyết định có thể đầu tư thêm bao nhiêu ở return cao.|Excess returns attract competition unless protected. Model erosion through competitive mechanisms, regulation and technology. Remaining market opportunity limits reinvestment at high returns.')
  ],'Retention đẹp vì hợp đồng chưa hết|Retention before contracts expire',
    'Công ty tăng price 15%, báo churn 1%; nhưng 80% hợp đồng chưa đến ngày renewal.|The firm raises price 15% and reports 1% churn, but 80% of contracts have not renewed.',
    ['Không coi toàn cohort đã chấp nhận giá mới.|Do not assume the whole cohort accepted the new price.','Tách renewed cohort, retention sau renewal, concessions và downgrade.|Isolate renewed customers, concessions, downgrades and retention.','Dự báo theo schedule reset và stress churn; kiểm tra có giữ margin sau discount.|Forecast by reset dates and stress churn and discounts.'],
    'Pricing power cần evidence sau quyết định khách thực sự có thể rời.|Pricing power needs evidence when customers can actually leave.');
  add('equity','forecast-roic',[
    S('Top-down và bottom-up phải hòa giải|Reconcile top-down and bottom-up','Market size × share và customers × frequency × price nên dẫn đến kết quả tương thích. Nếu forecast công ty tăng gấp đôi ngành mà không giải thích share gain, assumption thiếu cơ chế. Dùng segment và product mix khi unit economics khác nhau.|Market share and customer-level forecasts should reconcile. Growth far above the industry needs a share-gain mechanism. Separate segments where economics differ.'),
    S('Incremental ROIC khác historical average|Incremental versus historical ROIC','Tài sản cũ gần khấu hao hết có thể làm historical ROIC cao. New capacity mua theo replacement cost có return thấp hơn. Tính return trên vốn tăng thêm và thời gian ramp; acquisitions cần treatment goodwill nhất quán theo mục tiêu so sánh.|Depreciated assets can inflate historical returns. New capacity at replacement cost may earn less. Analyze incremental returns and ramp time, treating acquisition goodwill consistently for the comparison.'),
    S('Growth, reinvestment và cash|Growth, reinvestment and cash','Trong stable framework đơn giản, growth bằng reinvestment rate nhân return trên vốn tăng thêm. Profit tăng nhanh không đồng nghĩa FCFF tăng nếu capital intensity cao. Đừng forecast perpetual growth mà reinvestment bằng không khi economics cần assets.|In a simple stable framework, growth equals reinvestment rate times incremental capital return. High capital intensity can consume growing profits. Perpetual growth needs supporting assets where economics require them.')
  ],'Growth cao nhưng free cash thấp|High growth but little free cash',
    'NOPAT 100, mục tiêu growth 8%, expected incremental ROIC 10%; stable assumptions.|NOPAT 100, target growth 8% and expected incremental ROIC 10%, under stable assumptions.',
    ['Reinvestment rate cần 80%.|Required reinvestment rate is 80%.','Reinvestment 80, còn FCFF proxy 20.|Reinvestment is 80, leaving a simplified FCFF of 20.','Nếu ROIC là 20%, cần reinvest 40, còn cash 60; chất lượng growth khác.|At 20% ROIC, reinvestment is 40 and cash 60: different growth economics.'],
    'Cùng growth không cùng value khi return và capital need khác.|Equal growth does not imply equal value when capital returns differ.',
    F('ReinvestmentRate=frac(g;ROIC)','g: growth ổn định; ROIC: return trên vốn tăng thêm theo giả định; rate: tỷ lệ NOPAT tái đầu tư.|g: stable growth; ROIC: assumed incremental capital return; rate: NOPAT share reinvested.','8% chia 10%=80%.|8% divided by 10% gives 80%.','Không áp máy móc cho transition, negative profit hoặc model tài chính không cùng định nghĩa.|Do not apply mechanically in transitions, losses or inconsistent financial models.'));
  add('equity','valuation',[
    S('Multi-stage DCF và terminal value|Multi-stage DCF and terminal value','Dự báo giai đoạn riêng rồi terminal khi margin, reinvestment và growth đạt ổn định. Terminal ở cuối forecast phải discount về t=0. Tính next-year cash đúng: dùng CF sau terminal date, không lấy nhầm CF đã discount hoặc current year.|Forecast an explicit transition, then a stable terminal stage. Discount terminal value from the forecast endpoint. Use the cash flow after that date, not a current or already-discounted amount.'),
    S('EV-to-equity bridge và diluted shares|Bridge EV to equity and diluted shares','Trừ các claims phù hợp và cộng assets ngoài operations chưa tính, gồm surplus cash theo assumptions. Noncontrolling interests hoặc pension claims cần treatment nhất quán với cash. Diluted shares và option/convertible effects phải khớp numerator, tránh trừ rồi pha loãng hai lần.|Bridge operating value using consistent claims and nonoperating assets. Minority and pension claims must match cash-flow treatment. Align diluted shares and option/convertible effects without double-counting.'),
    S('Multiples và denominator bền vững|Multiples and sustainable denominators','Forward P/E khác trailing; EV/sales không biết margin; P/B liên quan return trên equity và accounting. So peers sau chuẩn hóa growth, risk và policies. Negative denominator làm multiple khó có ý nghĩa, không chỉ “rẻ vô cùng”.|Forward and trailing P/E differ; EV/sales ignores margins; P/B depends on returns and accounting. Normalize peers for growth, risk and policy. Negative denominators do not mean infinite cheapness.')
  ],'Terminal value nằm ở ngày nào?|On what date is terminal value?',
    'FCFF năm 1 là 10, năm 2 là 12; sau đó growth 3%, WACC 9%; net debt 40, 10 shares. Không khoản khác.|Year-one FCFF 10, year-two 12, then 3% growth at 9% WACC; net debt 40 and ten shares, no other items.',
    ['FCFF năm 3 là 12,36; terminal cuối năm 2 là 206.|Year-three FCFF is 12.36; terminal value at year two is 206.','EV hôm nay = 10/1,09 + (12+206)/1,09² ≈ 192,6606.|Today’s EV is about 192.6606.','Equity khoảng 152,6606; value/share 15,2661. Thử thay growth và WACC.|Equity is about 152.6606 and value/share 15.2661; stress growth and WACC.'],
    'Không cộng 206 trực tiếp vào PV hôm nay; đó là value ở cuối năm 2.|Do not add 206 directly to today’s PV; it is dated at year two.');
  add('equity','memo-risk',[
    S('Reverse DCF và variant perception|Reverse DCF and variant perception','Reverse DCF tìm combination assumptions làm value bằng price, không chỉ một growth duy nhất. So implied sales, margins và runway với khả năng ngành. Variant view phải có bằng chứng khác consensus, không chỉ cảm giác giá thấp.|Reverse DCF finds assumption combinations consistent with price. Compare implied sales, margins and runway with industry capacity. A variant view needs evidence, not merely a feeling that price is low.'),
    S('Downside probability và permanent loss|Downside and permanent loss','Scenario weights phải có lý do và uncertainty. Loss tạm thời do multiple khác loss khi business mất earning power hoặc bị dilution vì thiếu cash. Position size cần xét covariance, liquidity và khả năng chịu bear, không chỉ expected upside.|Explain scenario weights and uncertainty. Temporary repricing differs from lost earning power or forced dilution. Size positions using covariance, liquidity and downside capacity, not expected upside alone.'),
    S('Theo dõi thesis bằng KPI|Monitor a thesis using KPIs','Ghi driver, evidence threshold, kỳ quan sát và action. Nếu driver bị phá, cập nhật intrinsic value trước khi dùng giá rẻ hơn làm lý do mua thêm. Xem cả dữ kiện phản bác, tránh chỉ tìm xác nhận.|Record drivers, thresholds, observation periods and actions. Revalue broken drivers before treating lower prices as a buying opportunity. Seek disconfirming evidence as well as confirmation.')
  ],'Expected upside hấp dẫn nhưng bear quá nặng|Attractive expected upside with severe downside',
    'Value bull 150 xác suất 20%, base 100 xác suất 50%, bear 30 xác suất 30%; market 80.|Bull value 150 at 20%, base 100 at 50%, bear 30 at 30%; market price 80.',
    ['Probability-weighted value là 89.|Probability-weighted value is 89.','Implied expected return giản lược 11,25%, bear loss 62,5%.|Simplified expected return is 11.25%, while bear loss is 62.5%.','So required return, credibility của probabilities, timing và capacity chịu loss trước sizing.|Assess required return, probabilities, timing and loss capacity before sizing.'],
    'Weighted value là công cụ suy nghĩ dưới assumptions, không guaranteed fair price.|Weighted value is an assumption-based tool, not a guaranteed fair price.');

  add('fixed-income','structures-yields',[
    S('Indenture và embedded options|Indentures and embedded options','Đọc seniority, collateral, covenants, call, put và conversion. Callable issuer có thể refinance khi rates thấp, làm investor mất upside và phải reinvest rẻ. Floating coupon giảm một phần rate duration nhưng không loại credit hoặc reset risk.|Read seniority, collateral, covenants and call, put or conversion terms. Issuer calls can cap gains when rates fall and force low-rate reinvestment. Floating coupons do not remove credit or reset risk.'),
    S('YTM, current yield và holding return|YTM, current yield and holding return','Current yield chỉ coupon/price, bỏ capital gain/loss. YTM giải promised cash; realization còn cần không default và reinvestment phù hợp. Holding return khi bán trước hạn phụ thuộc exit yield và horizon; investor cùng bond có thể return khác.|Current yield excludes capital gains/losses. YTM solves promised flows, while realization depends on default and reinvestment. Early-sale returns depend on exit yields and horizon, so identical bonds can produce different investor returns.'),
    S('Full price và settlement|Full price and settlement','Accrued interest bù phần coupon tích lũy theo convention. Price quote clean không phải toàn cash cần thanh toán. Calendar, day count và ex-coupon conventions cần phù hợp; annual yield quote không tự dùng làm periodic discount rate.|Accrued interest compensates for coupon accrual under convention. Clean quotes differ from settlement cash. Match calendars, day counts and coupon conventions and convert annual yields appropriately.')
  ],'Mua premium bond lợi suất bao nhiêu?|What does a premium bond yield?',
    'Face 100, coupon cuối năm 8, còn đúng một năm; full price 104, không default.|Face 100, final coupon 8, exactly one year remaining and full price 104, without default.',
    ['Nhận 108 cuối năm, không chỉ coupon 8.|The final receipt is 108.','YTM một năm là 108/104−1 ≈ 3,846%.|One-year YTM is about 3.846%.','Current yield 8/104 ≈ 7,692% bỏ capital loss 4 khi trả par.|Current yield about 7.692% omits the four-point capital loss at redemption.'],
    'Coupon cao có thể đi cùng realized yield thấp nếu trả premium.|A high coupon can accompany a low yield when bought at a premium.');
  add('fixed-income','spot-curve',[
    S('Discount factors trước yield summary|Discount factors before yield summaries','Một discount factor định giá một đơn vị cash tại maturity. Bond cash ở nhiều ngày cần nhiều factors từ cùng curve framework. Par curve tóm coupon rate cho hypothetical par bonds; nó không trực tiếp là từng discount rate.|A discount factor prices one dated unit. Coupon cash needs maturity-specific factors in one framework. Par yields summarize coupons for par bonds rather than serving directly as all discount rates.'),
    S('Bootstrap từng bước|Bootstrap step by step','Dùng instrument ngắn để lấy factor đầu; với bond dài, trừ PV coupons đã biết để tìm factor cuối. Cần consistent clean/full price, day counts và payment dates. Sai data đầu có thể lan qua curve, nhất là đoạn ít instrument.|Infer the first factor from short instruments, then strip known coupon PVs from longer prices. Consistent full prices, dates and conventions matter because early errors can propagate through the curve.'),
    S('Curve shape và horizon return|Curve shape and holding returns','Roll-down có thể tạo return khi đi dọc curve không đổi, nhưng curve có thể shift hoặc twist. Forward chứa information về rates và risk premiums theo model; không chỉ là pure expectation. Stress cả level và shape.|Roll-down can add return on an unchanged curve, but curves shift and twist. Forwards incorporate pricing and possibly risk premiums, not pure expectations alone. Stress level and shape.')
  ],'Bootstrap spot hai năm|Bootstrap the two-year spot rate',
    'Zero một năm face 100 giá 96. Bond hai năm coupon 5 mỗi năm, face 100, full price 100; annual convention.|A one-year zero pays 100 and costs 96. A two-year bond pays annual coupons 5 plus face 100 and has full price 100.',
    ['Discount factor năm 1 là 0,96; PV coupon đầu 4,8.|Year-one factor is 0.96 and first coupon PV 4.8.','Phần PV 105 ở năm 2 là 95,2, nên DF₂=95,2/105≈0,906667.|PV of the final 105 is 95.2, giving DF₂ about 0.906667.','Spot annual hai năm khoảng 5,0210%; không dùng coupon 5% cho cả hai ngày.|Two-year annual spot is about 5.0210%, not automatically the 5% coupon at both dates.'],
    'Mỗi bước giải giá cash đã có, không cần đoán yield tương lai.|Each step solves current cash-flow prices rather than forecasting future yields.');
  add('fixed-income','duration-convexity',[
    S('Macaulay, modified và effective|Macaulay, modified and effective','Macaulay là thời gian PV-weighted, modified đo price sensitivity theo YTM; effective reprices với curve shifts khi cash có thể đổi. Không áp modified cash-fixed approximation cho callable mà không xem option effects. Units của yield change phải là decimal.|Macaulay is PV-weighted time; modified is YTM sensitivity; effective duration reprices potentially changing cash flows. Callable bonds need option-aware treatment. Yield changes must use decimal units.'),
    S('Convexity bổ sung approximation|Convexity improves the approximation','Duration là slope tại điểm; convexity thêm curvature. Với option-free positive convexity, cùng độ giảm yield thường tăng price nhiều hơn mức giảm price khi yield tăng tương ứng. Với embedded options, pattern có thể khác và approximation vẫn có residual.|Duration is a local slope and convexity adds curvature. Positive-convexity option-free bonds typically gain more on a rate fall than lose on an equal rise. Options can change this, and approximations retain errors.'),
    S('Key-rate và spread risk|Key-rate and spread risk','Match total duration có thể giữ rủi ro twist lớn. Key-rate durations đo các maturity nodes; spread duration đo sensitivity theo spread theo định nghĩa. Một duration number không mô tả hết currency, credit và liquidity.|Matching total duration can leave large twist exposure. Key-rate durations capture curve nodes and spread duration captures spread sensitivity. One duration does not capture credit, currency or liquidity.')
  ],'Đổi đơn vị 100 bps cho đúng|Use the correct units for 100 bps',
    'Modified duration 5, convexity 40; yield tăng 100 bps, cash fixed, dùng approximation chuẩn.|Modified duration 5 and convexity 40; yield rises 100 bps with fixed cash flows and the standard approximation.',
    ['100 bps = 0,01, không phải 1.|100 bps is 0.01, not 1.','Duration effect −5%; convexity adjustment +0,2%.|Duration effect is −5%, convexity adjustment +0.2%.','Net price change khoảng −4,8%; cần repricing để biết chính xác.|Approximate price change is −4.8%; reprice for an exact value.'],
    'Convexity correction không làm duration approximation trở thành giá chính xác.|Convexity does not make the approximation exact.',
    F('frac(ΔP;P)≈−DΔy+frac(C;2)(Δy)²','D: modified duration; C: convexity cùng convention; Δy: yield change decimal; ΔP/P: relative price change.|D: modified duration; C: convention-consistent convexity; Δy: decimal yield change; ΔP/P: relative price change.','D=5, C=40, Δy=0,01 cho −4,8%.|These inputs give −4.8%.','Local approximation; embedded options và curve shifts cần measure phù hợp.|Local approximation; use suitable measures for options and curve shifts.'));
  add('fixed-income','credit',[
    S('Issuer và issue ratings|Issuer versus issue risk','Cùng issuer có senior secured, unsecured và subordinated claims với recovery khác. Creditworthiness của issuer không tự xác định rating mọi issue. Đánh giá structural subordination khi cash và assets ở công ty con nhưng debt ở parent.|One issuer can have differently ranked claims and recoveries. Issuer quality does not determine every issue’s risk. Assess structural subordination when assets and cash sit below parent debt.'),
    S('Expected loss khác required spread|Expected loss versus spread','PD×LGD×EAD là loss expectation trong mô hình đơn giản, không là bond pricing đầy đủ. Timing default, discounting, liquidity và risk premium còn cần. Spread widening có thể làm mark-to-market lỗ trước khi cash mất.|The simple expected-loss product is not a full bond-pricing model. Default timing, discounting, liquidity and risk premiums matter. Widening spreads can cause losses before default.'),
    S('Debt-service analysis theo downside|Downside debt-service analysis','EBITDA coverage không cho biết cash còn sau capex, tax và working capital. Maturity wall tạo refinancing need ngay cả khi interest được trả. Stress cash, collateral và ability tiếp cận thị trường trong cùng bad state.|EBITDA coverage misses capex, tax and working capital. Maturity walls create funding needs despite adequate interest coverage. Stress cash, collateral and market access in the same adverse state.')
  ],'Credit spread tăng mà chưa default|Spreads widen without default',
    'Bond value 10 triệu, spread duration 4; spread tăng 150 bps; rates không đổi; bỏ convexity.|Bond value 10 million, spread duration 4 and spread widens 150 bps; rates unchanged, ignoring convexity.',
    ['Δspread=0,015.|Spread change is 0.015.','Price change xấp xỉ −6%, lỗ value 600.000.|Approximate price loss is 6%, or 600,000.','Không có default vẫn có market loss; rate hedge riêng không tự bù spread widening.|No default is needed for loss; a rate hedge does not automatically offset spread widening.'],
    'Phân biệt risk của cash promised với market value trước maturity.|Distinguish promised cash risk from interim market-value risk.');
  add('fixed-income','portfolio-hedge',[
    S('Immunization là quản lý surplus|Immunization manages surplus','Liability PV và duration matching nhằm giảm surplus sensitivity theo giả định. Single-payment horizon có intuition khác nhiều liabilities; convexity, cash-flow dispersion và reinvestment cùng quan trọng. Sau market moves cần rebalance, không coi match ban đầu là vĩnh viễn.|PV and duration matching seek to reduce surplus sensitivity. Multiple liabilities need more than single-horizon intuition; convexity, dispersion and reinvestment matter. Rebalance after changes.'),
    S('DV01 và hedge ratio theo dấu|DV01 and hedge signs','DV01 thường đo magnitude tiền đổi với một basis point theo convention. Long bond có thể cần short futures để giảm duration; chọn direction từ exposure. Futures hedge còn contract conversion và cheapest-to-deliver effects, không chỉ lấy face chia notional.|DV01 measures money sensitivity per basis point under a convention. Reducing long-bond duration often needs short futures. Include conversion and cheapest-to-deliver effects instead of dividing notionals alone.'),
    S('Liquidity là điều kiện triển khai|Liquidity enables implementation','Cash-flow matching vẫn chịu issuer default nếu instrument không an toàn. Derivative overlay giảm initial cash nhưng cần margin và counterparties. Liability date chính xác và currency quan trọng hơn một expected return cao không đúng ngày.|Cash matching can retain issuer default risk. Derivative overlays need margin and counterparty management despite low initial funding. Exact liability dates and currency matter more than unrelated high returns.')
  ],'Giảm DV01 có kiểm soát|Reduce DV01 deliberately',
    'Portfolio DV01 là 8.000 mỗi bp; target 5.000; một short futures giảm DV01 50 theo dữ kiện đã điều chỉnh contract.|Portfolio DV01 is 8,000 per bp, target 5,000; each short future removes 50 after contract adjustments.',
    ['Cần giảm DV01 3.000.|Reduce DV01 by 3,000.','Short 60 contracts theo hedge tuyến tính.|Short 60 contracts in the linear hedge.','Kiểm tra key-rate mismatch, basis, margin và cập nhật DV01 khi curve đổi.|Check key-rate mismatch, basis, margin and changing DV01.'],
    'Match DV01 tổng không chứng minh mọi liability risk đã được hedge.|Aggregate DV01 matching does not prove all liability risks are hedged.');

  add('derivatives','payoff-arbitrage',[
    S('Quyền và nghĩa vụ trước dấu payoff|Rights and duties before payoff signs','Long forward cam kết mua, short cam kết bán; long option có quyền không thực hiện, short option gánh nghĩa vụ nếu được exercise. Không suy premium nhỏ nghĩa risk nhỏ cho mọi bên. Xác định settlement cash hay physical và thời điểm payment.|A long forward commits to buy and a short to sell; option buyers may decline exercise, while sellers have obligations. Small premiums do not imply small risk for every party. Identify cash/physical settlement and timing.'),
    S('Replication theo từng trạng thái|Replication across states','Hai danh mục có cùng dòng tiền ở mọi trạng thái và cùng constraints phải có giá phù hợp no-arbitrage. Cùng expected payoff không đủ: distribution và timing có thể khác. Arbitrage còn yêu cầu giao dịch thực hiện được, không chỉ công thức chênh giá.|Replication matches every relevant state, not merely expected payoff. Timing and constraints matter. Arbitrage needs executable trades rather than just an algebraic price difference.'),
    S('Profit có financing cost|Profit includes financing','Option payoff chưa trừ premium; economic profit còn opportunity cost của premium và fees nếu bài yêu cầu. Forward initial fair value có thể bằng zero nhưng future exposure lớn. Luôn ghi convention khi minh họa bỏ time value.|Option payoff excludes premium; economic profit may include premium financing and fees. Zero initial forward value does not imply no future exposure. State conventions when ignoring time value.')
  ],'Payoff dương nhưng đầu tư lỗ|Positive payoff, negative profit',
    'Long European call strike 100, premium 8 trả t=0; underlying đáo hạn 105 sau một năm; financing premium 5%, bỏ fee.|A one-year European call has strike 100, premium 8 now, terminal price 105 and 5% premium financing; no fees.',
    ['Payoff cuối kỳ 5.|Terminal payoff is 5.','Premium quy về cuối kỳ 8,4.|Financed premium at maturity is 8.4.','Profit kinh tế cuối kỳ −3,4, khác profit bỏ financing −3.|Terminal economic profit is −3.4 versus −3 ignoring financing.'],
    'Dương payoff không phải bằng chứng trade có lãi sau toàn cost.|A positive payoff does not establish profit after costs.');
  add('derivatives','forwards-futures',[
    S('Price lúc ký khác value sau ký|Initial price versus later value','Fair forward delivery price làm value khởi đầu bằng zero trong mô hình, nhưng strike giao hàng giữ nguyên sau ký trong khi market forward price thay đổi. Value existing long liên quan chênh giá giao hàng hiện tại với giá cũ được discount phù hợp.|The fair delivery price gives zero initial value in the model. That price stays fixed while current forward prices move. Existing long value uses the appropriately discounted difference between current and contracted delivery prices.'),
    S('Income và storage trong carry|Income and storage in carry','Dividend hoặc coupon giảm net carry đối với người nắm underlying; storage tăng cost; convenience yield có thể bù cho physical commodity. Chọn discrete/continuous convention rõ và chỉ dùng các dòng trong thời hạn contract.|Income reduces net carry, storage raises it, and convenience yield can offset physical holding cost. Specify compounding and include only relevant contract-period flows.'),
    S('Futures marking và margin|Futures marking and margin','Daily settlement đưa profit/loss về cash sớm; forward thường khác timing. Khi rates stochastic, futures và forward prices có thể khác do covariance và settlement. Dù hedge cuối kỳ hiệu quả, margin trong kỳ vẫn cần nguồn.|Daily settlement changes cash timing versus forwards. Stochastic rates can create pricing differences through covariance and settlement. Effective terminal hedges still need interim margin funding.')
  ],'Định giá long forward đã ký|Value an existing long forward',
    'Long contract delivery price K=100. Còn một năm, fair forward hiện tại 110; discount rate 5%, cùng terms, không counterparty cost.|An existing long has delivery price 100. One year remains; the current matching forward price is 110 and discount rate 5%, ignoring counterparty costs.',
    ['Long cũ có lợi vì được mua rẻ hơn market forward 10 ở maturity.|The old long gains a ten-unit delivery-price advantage.','PV advantage 10/1,05≈9,524.|PV of the advantage is about 9.524.','Đây là value hôm nay, không phải original price 100 hay notional.|This is current value, not the original delivery price or notional.'],
    'Giữ ba khái niệm riêng: spot, forward price và contract value.|Keep spot, forward delivery price and contract value distinct.',
    F('V_long=frac(F−K;1+r)','F: fair forward hiện tại cùng maturity; K: contracted delivery price; r: rate cho thời gian còn lại trong ví dụ một kỳ.|F: current matching forward; K: contracted price; r: remaining-period rate.','(110−100)/1,05≈9,524.|The stated inputs give about 9.524.','Giả định cùng underlying/terms, một kỳ, không điều chỉnh tín dụng hoặc collateral phức tạp.|Assume matching terms, one period and no additional credit/collateral adjustments.'));
  add('derivatives','options-greeks',[
    S('Intrinsic và time value|Intrinsic and time value','Moneyness so spot với strike theo call/put; premium còn time value và volatility. Option out-of-the-money chưa vô giá trị trước expiry. Volatility cao thường làm long plain-vanilla options giá cao hơn trong model phù hợp nhưng không nói underlying sẽ tăng.|Moneyness compares spot and strike; premiums also reflect time and volatility. Out-of-money options can retain value before expiry. Higher volatility generally raises plain-vanilla option values without forecasting underlying direction.'),
    S('Delta, gamma, vega và theta cùng tồn tại|Multiple sensitivities coexist','Delta hedge là local theo spot; gamma làm delta đổi, vega theo implied volatility và theta theo thời gian. Short options có thể lãi nhiều ngày nhỏ rồi lỗ tail lớn. Không dùng lịch sử Sharpe cao để bỏ qua asymmetric exposure.|Delta is local spot sensitivity; gamma changes delta, vega responds to implied volatility and theta to time. Short options may earn small gains before large tail losses. High historical Sharpe does not eliminate asymmetry.'),
    S('Put–call parity và assumptions|Parity and assumptions','Parity European cần cùng underlying, strike và expiry, với treatment income phù hợp. American exercise và dividends có thể thay equality cơ bản bằng quan hệ khác. Dùng parity để kiểm tra pricing sau transaction và funding constraints, không so options lệch terms.|European parity needs matching underlying, strike and expiry with appropriate income treatment. American exercise and dividends can change the basic relation. Compare matching terms and account for practical costs.')
  ],'Dùng parity kiểm tra put|Check a put using parity',
    'Không dividend; spot 100, European call 8, PV strike 95; cùng maturity/strike, không phí.|No dividends; spot 100, European call 8 and strike PV 95, matching terms and no fees.',
    ['Call cộng PV strike là 103.|Call plus strike PV is 103.','Put cộng spot phải bằng 103, suy put 3.|Put plus spot must equal 103, so put value is 3.','Nếu quote khác, kiểm tra contract terms, bid–ask và ability thực hiện trước kết luận arbitrage.|If quotes differ, inspect terms, bid–ask and execution before claiming arbitrage.'],
    'Parity so portfolio payoff tương đương, không dự đoán giá tương lai.|Parity compares equivalent payoff portfolios rather than forecasting prices.');
  add('derivatives','swaps',[
    S('Par swap rate và annuity factor|Par swap rates and annuity factors','Fixed leg là rate nhân notional nhân accrual tại mỗi payment. Với single-curve par vanilla swap ngay reset và assumptions chuẩn, floating PV nối discount factors; fixed rate cân hai legs. Multi-curve, currency và collateral cần treatment phù hợp.|The fixed leg pays rate times notional and accrual each date. In a standard single-curve reset-date model, floating PV connects discount factors and the par rate balances legs. Multi-curve, currency and collateral need suitable treatment.'),
    S('Dấu value theo người nắm|Value signs depend on the holder','Pay-fixed có value PV floating trừ PV fixed; receive-fixed ngược lại. Khi rates tăng, fixed payer thường có lợi, giữ yếu tố khác. Không đảo dấu vì nhìn coupon fixed cao hay thấp riêng lẻ; tính cả future legs.|A fixed payer values floating receipts less fixed payments; a receiver reverses it. Rising rates generally favor the payer, all else equal. Value both future legs rather than one coupon.'),
    S('Counterparty và collateral|Counterparty and collateral','OTC swap có replacement exposure và collateral calls; netting chỉ có lợi nếu enforceable theo arrangement. Notional không phải current credit exposure, nhưng zero market value không xóa future exposure. Document thresholds, eligible collateral và settlement currency.|OTC swaps involve replacement exposure and collateral calls. Netting depends on enforceability. Notional differs from current exposure, but zero current value does not remove future exposure. Review collateral terms and currency.')
  ],'Tìm fixed rate cho swap hai năm|Find a two-year fixed swap rate',
    'Single-curve, annual payments, start tại reset; discount factors D₁=0,96, D₂=0,91; accrual mỗi kỳ 1, notional 100.|Single-curve annual swap starting at reset, discount factors 0.96 and 0.91, annual accruals one and notional 100.',
    ['Floating leg PV theo assumptions là 100×(1−0,91)=9.|Floating PV is 9 under the assumptions.','Fixed annuity PV trên mỗi 1 rate là 100×(0,96+0,91)=187.|Fixed-leg rate annuity is 187.','Par rate 9/187≈4,813%; initial legs cùng PV 9.|Par rate is about 4.813%, equating both leg PVs to 9.'],
    'Công thức đơn giản này không thay mọi multi-curve hoặc off-reset valuation.|This simplified result does not replace multi-curve or off-reset valuation.',
    F('K=frac(1−D₂;D₁+D₂)','K: par fixed rate; D₁,D₂: discount factors đến hai ngày trả; accrual đều 1.|K: par fixed rate; D₁,D₂: payment-date discount factors; accruals are one.','0,09/1,87≈4,813%.|0.09/1.87 is about 4.813%.','Single-curve vanilla reset-date model với annual accruals.|Single-curve vanilla reset-date model with annual accruals.'));
  add('derivatives','hedge-design',[
    S('Minimum variance hedge và đơn vị|Minimum-variance hedging and units','Hedge ratio theo thay đổi giá cần correlation và volatilities cùng horizon, đơn vị. Từ ratio sang số contracts còn quy mô spot, contract size và price conventions. Không dùng một tỷ lệ 0,8 trực tiếp như số contracts.|Price-change hedge ratios require compatible correlation, volatility, units and horizon. Contract counts also require exposure and contract sizes. A ratio such as 0.8 is not a contract count.'),
    S('Basis và dynamic exposure|Basis and changing exposure','Cross-hedge dùng instrument không trùng exposure nên residual basis có thể lớn lúc stress. Forecast sales hoặc imports đổi làm hedge size cần đổi. Nếu exposure không chắc chắn, options hoặc staged hedging có trade-off cost và flexibility.|Cross-hedges retain basis risk that can grow in stress. Changing sales/import forecasts change hedge needs. Options or staged hedges can trade cost for flexibility under uncertain exposure.'),
    S('Đánh giá theo mục tiêu tổng|Evaluate the combined objective','Hedge loss có thể đi cùng gain exposure gốc, là đúng mục tiêu. Tính combined cash, volatility và tail, cùng premiums/margin costs. Accounting hedge designation khác economic hedge; hiệu quả kinh tế không tự đáp ứng reporting rules.|Hedge losses can offset original gains as intended. Evaluate combined cash, volatility, tails and funding costs. Economic hedging and accounting designation are distinct.')
  ],'Cross-hedge không cần full notional|A cross-hedge need not use full notional',
    'Giả sử các đơn vị giá tương thích: correlation 0,8; spot-change volatility 3; futures-change volatility 4. Spot exposure 1.000 đơn vị, mỗi contract 100.|Assume compatible price units: correlation 0.8, spot-change volatility 3, futures-change volatility 4; exposure 1,000 units and contract size 100.',
    ['Minimum-variance ratio 0,8×3/4=0,6.|The minimum-variance ratio is 0.6.','Số contract magnitude 0,6×1.000/100=6.|Contract magnitude is six.','Chọn long/short theo risk cần bù; kiểm tra estimation stability và basis.|Choose direction from the exposure and inspect estimate stability and basis.'],
    'Ratio giảm variance theo assumptions, không bảo đảm zero loss.|The ratio targets variance under assumptions, not zero loss.');

  add('alternatives','features-fees',[
    S('Commitment, called capital và NAV|Commitment, called capital and NAV','Commitment là nghĩa vụ góp tối đa theo terms; called capital là phần được yêu cầu; paid-in là đã góp; NAV là giá trị ròng hiện tại. Distributions có thể gồm hoàn vốn, không chỉ profit. Theo dõi uncalled commitments như nhu cầu liquidity có điều kiện.|Commitments, calls, paid-in capital and NAV are distinct. Distributions can return capital rather than profit. Track undrawn commitments as contingent liquidity needs.'),
    S('Waterfall và high-water mark|Waterfalls and high-water marks','Hurdle, catch-up, high-water mark và clawback giải các cơ chế khác nhau. High-water mark thường hạn chế tính incentive lại trên mức phục hồi cũ theo terms; không tự bảo đảm manager hoàn phí. Đọc order fee calculation và gross/net base.|Hurdles, catch-ups, high-water marks and clawbacks differ. A high-water mark can prevent recharging performance on recovery but does not automatically refund fees. Read fee order and base.'),
    S('Đo liquidity budget của LP|Budget LP liquidity','Capital calls và distributions có thể cùng xấu khi markets giảm. Không dùng kỳ vọng distribution như cash chắc chắn để trả call. Dự trữ, credit facilities và secondary-sale discounts cần stress riêng.|Calls and distributions can deteriorate together in stress. Expected distributions are not certain funding for calls. Stress reserves, credit facilities and secondary discounts.')
  ],'Tính fee đúng thứ tự hợp đồng|Apply the contractual fee sequence',
    'Đầu kỳ NAV 100, gross cuối kỳ trước fees 120. Management fee 2% beginning NAV, incentive 20% gain sau management, không hurdle/HWM khác.|Beginning NAV 100, gross ending NAV 120; management fee 2% of opening NAV, then 20% incentive on gains after management, no other hurdles or marks.',
    ['Management fee 2, còn 118.|Management fee is 2, leaving 118.','Incentive base gain 18, fee 3,6.|Incentive gain is 18, fee 3.6.','Net NAV 114,4, net return 14,4%; đổi fee base/order sẽ đổi đáp án.|Net NAV is 114.4 and return 14.4%; different terms produce different answers.'],
    'Không áp cụm “2 và 20” như một công thức duy nhất cho mọi quỹ.|The label two-and-twenty is not a universal calculation.');
  add('alternatives','real-assets',[
    S('NOI, cash after capex và debt service|NOI versus investor cash','NOI loại financing nhưng còn cần recurring capex, leasing commissions và tenant improvements theo analysis. Rental yield cao có thể bị maintenance và vacancy ăn hết. So lease duration, reset và tenant credit để dự báo cash bền vững.|NOI is before financing and may omit recurring capex, commissions and improvements. Maintenance and vacancy can consume rental yield. Assess lease resets and tenant credit for durable cash.'),
    S('Cap rate không phải discount rate giống hệt|Cap rates are not identical to discount rates','Direct cap rate gắn stabilized income với price; discount rate cho chuỗi cash theo thời gian. Quan hệ cap≈r−g chỉ đúng trong perpetuity đơn giản với định nghĩa cash nhất quán. Không suy growth chỉ từ cap mà bỏ chất lượng asset.|Cap rates relate stabilized income to price; discount rates price a cash stream. The simple r-minus-g relation requires a compatible perpetuity. Asset quality and cash definitions matter.'),
    S('Infrastructure phân bổ demand risk|Infrastructure allocates demand risk','Toll road user-pay chịu traffic; availability payment gắn tài sản sẵn dùng và có counterparty risk. Regulation có thể giới hạn tariffs dù inflation tăng. Construction completion, concession expiry và refinancing ảnh hưởng return equity.|User-pay roads face traffic risk; availability payments depend on availability and counterparty. Regulation can constrain tariff pass-through. Completion, concession expiry and refinancing affect equity returns.')
  ],'Property value đổi làm equity nhạy hơn|Property repricing amplifies equity losses',
    'Stabilized NOI 10, cap rate từ 5% lên 6,25%; debt cố định 120, không cash hoặc claim khác.|Stable NOI 10; cap rate rises from 5% to 6.25%; debt stays 120, with no other claims or cash.',
    ['Property value từ 200 xuống 160, giảm 20%.|Property value falls from 200 to 160, down 20%.','Equity từ 80 xuống 40, giảm 50%.|Equity falls from 80 to 40, down 50%.','Kiểm tra covenant, liquidity và sale costs ngoài phép bridge đơn giản.|Check covenants, liquidity and sale costs beyond the simple bridge.'],
    'Real asset không tự là inflation hedge hoàn hảo cho leveraged equity.|Real assets do not automatically provide perfect inflation hedges for leveraged equity.');
  add('alternatives','private-capital',[
    S('Preference thay đổi distribution|Preferences change distributions','Liquidation preference trả một lớp trước common; participating và nonparticipating khác nhau. Conversion có thể cho investor chọn common khi upside cao hơn. Ownership headline không đủ, cần waterfall từng exit scenario với cap table đầy đủ.|Preferences rank claims ahead of common; participation and conversion alter outcomes. Headline ownership is insufficient. Model the full cap table across exits.'),
    S('LBO drivers phải tách|Separate LBO return drivers','Equity return có thể đến operating improvement, debt paydown, multiple change và leverage ban đầu. Debt repayment cần actual cash sau tax, capex và WC. Không gọi leverage-generated return là operating alpha.|LBO equity returns combine operations, debt paydown, multiples and initial leverage. Debt repayment needs cash after tax, capex and working capital. Leverage-generated returns are not operating alpha.'),
    S('Private credit và covenant|Private credit and covenants','Illiquidity premium đi cùng underwriting, concentration và enforcement. Covenant không tự thu tiền nếu collateral yếu hoặc lender không enforce được. Amendment có thể cải thiện recovery nhưng cũng trì hoãn nhận diện risk.|Illiquidity premiums require underwriting and enforcement. Covenants do not ensure recovery from weak collateral. Amendments may preserve value or delay risk recognition.')
  ],'1× nonparticipating preference|A one-times nonparticipating preference',
    'Investor góp 2 triệu, sở hữu 20% fully converted, có 1× nonparticipating liquidation preference; exit proceeds cho equity 5 triệu, không debt/claim khác.|Investor puts in 2 million for 20% fully converted ownership with a one-times nonparticipating preference. Equity exit proceeds are 5 million, with no other claims.',
    ['Theo conversion, 20% cho 1 triệu.|Conversion gives 1 million.','Theo preference được 2 triệu, không nhận thêm 20% phần còn lại.|Preference gives 2 million without further participation.','Chọn preference theo terms; common nhận 3 triệu.|Under the terms the preference is chosen; common receives 3 million.'],
    '20% ownership không buộc mọi exit phải chia 20% proceeds.|20% ownership does not force a 20% share of every exit.');
  add('alternatives','hedge-commodities',[
    S('Long/short không tự market neutral|Long/short is not automatically neutral','Net notional zero vẫn có beta khác nếu longs beta cao và shorts beta thấp. Factor, sector và liquidity mismatch có thể lớn. Tách gross exposure, net, beta-adjusted exposure và financing. Short squeeze có thể buộc đóng vị thế trước khi thesis đúng.|Zero net notional can retain beta when long and short betas differ. Analyze gross, net, beta, factors, financing and liquidity. Squeezes can force exit before a thesis is realized.'),
    S('Commodity futures total return|Commodity futures total return','Futures strategy chịu price movements, collateral return, roll implementation và fees. Contango thường tạo khó cho long rolling, nhưng không đủ dự báo total return âm. Nếu futures curve đổi, không cộng từng thành phần như chúng độc lập cố định.|Futures returns involve price changes, collateral, roll implementation and fees. Contango can hurt long rolling but does not guarantee negative total return. Curve changes make components interdependent.'),
    S('Strategy risks khác nhau|Different strategy risks','Merger arbitrage chịu deal breaks, relative value chịu basis và leverage, macro chịu view và timing. Historical returns ngắn có thể bỏ tail hiếm. Stress đúng event mechanism thay vì chỉ lấy normal distribution chung.|Merger arbitrage has deal-break risk, relative value basis/leverage risk and macro timing risk. Short histories can miss rare tails. Stress the mechanism rather than a universal normal distribution.')
  ],'Net zero nhưng market beta dương|Zero net but positive market beta',
    'Long 100 có beta 1,5, short 100 có beta 0,7; NAV 100, bỏ nonlinear effects.|Long 100 at beta 1.5 and short 100 at beta 0.7; NAV 100, ignoring nonlinear effects.',
    ['Gross notional/NAV là 200%, net notional 0%.|Gross exposure is 200% and net notional zero.','Beta-equivalent exposure là 150−70=80, tức portfolio beta khoảng 0,8.|Beta-equivalent exposure is 80, implying portfolio beta about 0.8.','Market tăng 1% có first-order market contribution khoảng 0,8% NAV, trước selection và cost.|A 1% market rise contributes about 0.8% of NAV before selection and costs.'],
    'Dollar neutrality và beta neutrality là hai điều kiện khác nhau.|Dollar neutrality and beta neutrality are different.');
  add('alternatives','valuation-risk',[
    S('MOIC, DPI, RVPI và TVPI|MOIC, DPI, RVPI and TVPI','Phân phối cash/paid-in là DPI; residual NAV/paid-in là RVPI; tổng là TVPI theo cùng basis. MOIC của deal và fund multiple cần rõ gross/net. IRR thêm timing, có thể chịu ảnh hưởng subscription lines và distribution sớm.|DPI measures cash distributions over paid-in, RVPI residual value and TVPI their sum. Clarify deal/fund and gross/net multiples. IRR adds timing and can be affected by subscription lines and early distributions.'),
    S('Smoothing và selection bias|Smoothing and selection bias','Appraisal lags làm volatility và correlation nhìn thấp. Survivorship bỏ quỹ đóng, backfill thêm lịch sử tốt sau khi fund nổi tiếng. Không tối ưu allocation trên những statistics này như dữ liệu market liquid hoàn hảo.|Appraisal lags can understate volatility and correlation. Survivorship omits closed funds; backfill adds selected successful histories. Do not optimize as if these were unbiased liquid-market returns.'),
    S('Due diligence valuation|Valuation due diligence','So marks với transactions, subsequent exits, methodology và independent review. NAV audit không loại uncertainty kinh tế. Với concentration cao, chạy range asset values và funding downside thay vì chỉ dùng reported NAV làm chắc chắn.|Compare marks with transactions, exits, methods and independent review. Audits do not remove valuation uncertainty. Concentrated funds need value ranges and funding downside, not certainty at reported NAV.')
  ],'Đã trả vốn chưa?|Has capital actually been returned?',
    'Paid-in 100, distributions 40, residual NAV 90, cùng net basis.|Paid-in capital 100, distributions 40 and residual NAV 90 on a consistent net basis.',
    ['DPI 0,4; RVPI 0,9.|DPI is 0.4 and RVPI 0.9.','TVPI 1,3, nhưng mới nhận cash 40, không phải 130.|TVPI is 1.3, but only 40 cash has been received.','Stress residual mark và exit timing trước khi tài trợ nghĩa vụ mới từ NAV.|Stress residual marks and exit timing before treating NAV as funding.'],
    'Một multiple tốt có thể phụ thuộc phần lớn vào value chưa realize.|An attractive multiple may rely heavily on unrealized value.',
    F('TVPI=frac(Distributions+ResidualNAV;PaidIn)','Distributions: cash phân phối; ResidualNAV: giá trị còn lại; PaidIn: vốn đã góp cùng basis.|Distributions: paid-out cash; ResidualNAV: remaining net value; PaidIn: contributed capital on the same basis.','(40+90)/100=1,3.|The case gives 1.3.','TVPI không xét timing hoặc chắc chắn realize; không thay IRR và cash schedule.|TVPI ignores timing and realization uncertainty; retain IRR and a cash schedule.'));

  add('portfolio','ips',[
    S('Required, desired và feasible return|Required, desired and feasible returns','Desired return là mong muốn; required return từ mục tiêu và nguồn lực; feasible return bị giới hạn bởi markets và risk capacity. Nếu ba thứ không khớp, thay savings, spending hoặc goals thay vì luôn tăng leverage. Ghi after-tax/real hay nominal rõ.|Desired returns are wishes, required returns follow goals and resources, feasible returns depend on markets and risk capacity. Reconcile gaps through savings, spending or goals rather than automatically using leverage. Specify tax and inflation basis.'),
    S('Willingness và ability chịu risk|Willingness and ability','Khách thích biến động không có nghĩa chịu được permanent loss. Ability phụ thuộc tài sản, income, debt, dependents và timing goals. Khi hai chiều khác nhau, cần trao đổi và thiết kế phù hợp, không chọn mức cao hơn mặc định.|Willingness is not financial capacity for permanent loss. Capacity depends on assets, income, debt, dependents and timing. Resolve differences through discussion and suitable design rather than defaulting to the higher risk level.'),
    S('IPS là quy trình có update triggers|IPS is a process with triggers','Định nghĩa allowable investments, bands, benchmark, review và authority. Update khi objectives hoặc constraints đổi, không mỗi lần market giảm. Cần biết ai đề xuất và ai phê duyệt deviations để strategy được thực hiện có kỷ luật.|Specify assets, bands, benchmark, review and authority. Update for changed circumstances rather than every downturn. Assign approval rights for deviations.')
  ],'Return cần thiết vượt capacity|Required return exceeds capacity',
    'Khách có 1 tỷ, muốn 2 tỷ sau 5 năm, không góp thêm, trước tax và fees; chỉ chấp nhận risk thấp.|A client has 1 billion and wants 2 billion in five years without contributions, before tax and fees, accepting only low risk.',
    ['Required compound return khoảng 14,87%/năm.|Required compounded return is about 14.87% annually.','Không thể hứa return đó với low risk chỉ bằng chọn sản phẩm.|Product selection cannot promise that return at low risk.','Trao đổi thêm savings, kéo horizon hoặc giảm goal; lập IPS feasible.|Discuss contributions, horizon or goals and establish a feasible IPS.'],
    'Tính required return là đầu vào đối thoại, không cam kết kết quả.|The required return informs the conversation rather than promises an outcome.');
  add('portfolio','risk-return',[
    S('Return aggregation theo đúng bài toán|Aggregate returns for the question','Within-period portfolio return dùng weights đầu kỳ và constituent returns theo assumptions. Across-time wealth growth cần compound. Arithmetic mean không dự báo wealth chính xác khi volatility lớn; income, fees và cash flows phải tách.|Within-period returns use beginning weights under suitable assumptions; across-time growth compounds. Arithmetic means do not directly describe wealth growth, especially with volatility. Separate income, fees and external flows.'),
    S('Variance nhờ covariance|Variance depends on covariance','Tài sản ít tương quan có thể giảm portfolio variance ngay cả khi từng volatility cao. Negative correlation không đảm bảo risk zero với mọi weights. Correlation gần stress có thể tăng; benchmark diversification dựa nhiều regimes.|Low correlations can reduce variance despite volatile components. Negative correlation does not ensure zero risk at arbitrary weights. Stress correlations can differ; examine multiple regimes.'),
    S('Downside và liquidity risk|Downside and liquidity risk','Standard deviation xử lý upside/downside đối xứng; skew, drawdown, VaR và expected shortfall hỏi khác. VaR không mô tả maximum loss. Asset illiquid có thể mượt giá nhưng khó bán đúng lúc, cần cash stress ngoài return distribution.|Volatility treats both tails symmetrically; drawdown, VaR and expected shortfall ask different questions. VaR is not maximum loss. Illiquid smoothed assets need separate cash stress.')
  ],'Hai tài sản cùng volatility vẫn giảm risk|Equal-volatility assets can diversify',
    'Hai tài sản volatility 20% mỗi năm, weights 50/50, correlation 0; dùng variance model chuẩn.|Two assets each have 20% annual volatility, equal weights and zero correlation in the standard variance model.',
    ['Variance mỗi weighted component là 0,01.|Each weighted variance contribution is 0.01.','Tổng variance 0,02, volatility khoảng 14,14%.|Total variance is 0.02 and volatility about 14.14%.','Nếu correlation lên 1, volatility thành 20%; diversification benefit phụ thuộc covariance.|At correlation one volatility is 20%; the benefit depends on covariance.'],
    'Không cộng volatility theo weights và bỏ covariance.|Do not replace portfolio variance with weighted component volatilities.',
    F('σ_p²=w₁²σ₁²+w₂²σ₂²+2w₁w₂ρσ₁σ₂','w: weights; σ: asset volatility; ρ: correlation; σ_p: portfolio volatility.|w: weights; σ: asset volatility; ρ: correlation; σ_p: portfolio volatility.','Dùng w=0,5, σ=0,2 và ρ=0 rồi lấy căn variance.|Use equal 0.5 weights, 0.2 volatilities and zero correlation, then take the square root.','Cùng horizon và estimators; correlation không được giả cố định trong stress.|Match horizons and estimation; stress correlations rather than assuming permanence.'));
  add('portfolio','capm',[
    S('Security market line và beta|The security market line and beta','CAPM nối expected return với systematic beta theo assumptions equilibrium. Một point cao hơn line dùng forecast của bạn có thể gợi underpricing, nhưng forecast và beta có error. Không nhầm Security Market Line với efficient portfolio Capital Market Line theo total volatility.|CAPM relates expected return to systematic beta under equilibrium assumptions. A forecast above the line may suggest underpricing but estimates can be wrong. Distinguish the SML from the CML’s efficient-portfolio volatility relation.'),
    S('Factor exposure và alpha|Factors and alpha','Return vượt risk-free không tự là alpha; phần beta premium là expected compensation. Multi-factor models có thể giải thích phần CAPM alpha bằng value, size hoặc momentum. Chọn model theo câu hỏi và kiểm tra exposure stability.|Excess over cash is not automatically alpha; beta premiums compensate risk. Multifactor models may explain CAPM alpha through other exposures. Match the model to the decision and test stability.'),
    S('Estimation và leverage|Estimation and leverage','Beta estimate phụ thuộc window, frequency và market proxy. Leverage làm equity beta thay đổi khi business exposure không đổi. Small sample hoặc stale prices gây noise; dùng peer/adjusted estimates có lý do thay vì chọn số cho valuation đẹp.|Beta depends on window, frequency and proxy. Leverage changes equity beta even with unchanged business risk. Noisy data call for justified peer or adjusted estimates, not convenient numbers.')
  ],'Return cao có phải alpha?|Is a high return alpha?',
    'Risk-free 3%, market return 11%, portfolio beta 1,5; portfolio return 14%, dùng single-period CAPM attribution giản lược.|Risk-free is 3%, market return 11%, portfolio beta 1.5 and portfolio return 14%; use a simplified single-period CAPM comparison.',
    ['CAPM-implied return là 3%+1,5×8%=15%.|CAPM-implied return is 15%.','Realized alpha proxy là −1 điểm %, dù portfolio hơn market 3 điểm.|The realized alpha proxy is −1 percentage point despite beating the market by three.','Một kỳ không chứng minh skill; xem model fit, timing và residual risk.|One period does not establish skill; examine fit, timing and residual risk.'],
    'So market return mà bỏ beta dễ thưởng cho việc chịu risk nhiều hơn.|Ignoring beta can reward higher risk rather than skill.');
  add('portfolio','rebalancing',[
    S('Calendar và tolerance bands|Calendar and tolerance bands','Calendar dễ quản lý nhưng có thể trade khi drift nhỏ; bands phản ứng risk drift nhưng cần monitoring. Width nên gắn volatility, correlation, cost và mandate. Không đổi bands sau outcome chỉ để hợp thức hóa vị thế cũ.|Calendar rules are simple but can trade small drifts; bands respond to risk but require monitoring. Width depends on volatility, correlation, costs and mandate. Do not revise bands solely to justify outcomes.'),
    S('Rebalance bằng cash flows|Rebalance with cash flows','Dùng contributions mua asset thiếu weight hoặc withdrawals từ asset dư có thể giảm turnover. Nhưng phải tính weights sau cash flow chứ không chỉ trên tổng cũ. Trước trade xem tax lots, spread và asset liquidity.|Contributions and withdrawals can correct weights with less trading. Compute targets on post-flow assets and consider tax lots, spreads and liquidity.'),
    S('Tax-aware implementation|Tax-aware implementation','Realized gains tạo tax theo jurisdiction; tax-loss harvesting có hạn chế như wash-sale tùy nơi. Không giữ asset quá rủi ro vô hạn vì sợ tax. So PV tax cost với risk-control benefit và alternative trades.|Tax depends on jurisdiction and loss harvesting can face restrictions. Avoid indefinitely retaining unsuitable risk merely to defer tax. Compare tax PV, risk control and alternative trades.')
  ],'Dòng góp mới giúp giảm bán|New contributions reduce selling',
    'Portfolio 100 gồm equity 70, bonds 30; target equity 60%. Nhận thêm cash 10; giả sử không price change hoặc tax.|A 100 portfolio holds 70 equity and 30 bonds; target equity 60%. It receives 10 new cash, with no price changes or tax.',
    ['Tổng mới 110; target equity 66 và bonds 44.|New total is 110; target equity 66 and bonds 44.','Đưa cash 10 vào bonds rồi bán equity 4 để mua bonds thêm 4.|Allocate 10 cash to bonds, then sell 4 equity to buy 4 bonds.','Nếu quên post-flow total có thể bán sai 10 equity.|Ignoring the post-flow total can lead to an incorrect equity sale of 10.'],
    'Target percentages phải nhân đúng tổng tài sản sau external flow.|Apply target weights to the correct post-flow total.');
  add('portfolio','wealth-risk',[
    S('Human capital và portfolio concentration|Human capital and concentration','Lương phụ thuộc cùng ngành với cổ phiếu nắm giữ làm risk tổng cao hơn account nhìn thấy. Business owner còn chịu liquidity và guarantee risk. Đưa assets và liabilities ngoài account vào capacity trước allocation.|Salary and investments in one industry concentrate total risk. Business owners also face illiquidity and guarantees. Include off-account assets and liabilities before assessing capacity.'),
    S('Sequence risk khi rút tiền|Sequence risk during withdrawals','Khi có withdrawals, cùng một tập returns nhưng thứ tự khác có thể tạo ending wealth khác. Lỗ đầu kỳ khiến phải bán nhiều units để chi cố định. Cash reserve và allocation giảm forced sales nhưng có opportunity cost, cần cân đối.|With withdrawals, return order affects ending wealth. Early losses require selling more units for fixed spending. Reserves and allocation can reduce forced sales but entail opportunity costs.'),
    S('Risk transfer và behavioral guardrails|Risk transfer and behavioral guardrails','Insurance xử lý severity theo terms, không thay savings cho mọi chi thường xuyên. Precommitment về review, diversification và spending giúp giảm panic. Đánh giá behavior bằng tình huống thật, không chỉ bảng hỏi khi thị trường tốt.|Insurance addresses covered severe events rather than all routine spending. Precommitted review and diversification rules can reduce panic. Assess behavior through scenarios, not only calm-market questionnaires.')
  ],'Cùng returns, khác thứ tự rút tiền|Equal returns, different withdrawal sequences',
    'Bắt đầu 100, rút 10 cuối mỗi năm. Hai năm có returns −20% và +25%; so hai thứ tự, không fees/tax.|Start with 100 and withdraw 10 at each year-end. Two annual returns are −20% and +25%; compare their order without fees or tax.',
    ['Lỗ trước: năm 1 còn 70; năm 2 tăng thành 87,5 rồi rút còn 77,5.|Loss first leaves 70, then 87.5 before the second withdrawal and 77.5 after.','Lãi trước: năm 1 còn 115; năm 2 còn 92 rồi rút còn 82.|Gain first leaves 115, then 92 before withdrawal and 82 after.','Không withdrawals, cả hai về 100; chênh 4,5 xuất hiện do timing chi tiền.|Without withdrawals both end at 100; spending timing creates the 4.5 difference.'],
    'Retirement planning phải model cash-flow sequence, không chỉ average return.|Retirement planning needs cash-flow sequences rather than average return alone.');

  const book=window.CFA_TEXTBOOK;
  if(!book)throw new Error('Textbook must load before core-depth.');
  book.sources.suitability=['CFA Institute · Standard III(C) Suitability','https://www.cfainstitute.org/standards/professionals/code-ethics-standards/standards-of-practice-iii-c'];
  book.sources.regression=['CFA Institute · Multiple Regression','https://www.cfainstitute.org/insights/professional-learning/refresher-readings/2026/multiple-regression'];
  book.sources.tax=['IFRS Foundation · IAS 12 Income Taxes','https://www.ifrs.org/issued-standards/list-of-standards/ias-12-income-taxes/'];
  book.sources.forwards=['CFA Institute · Forward Commitments','https://www.cfainstitute.org/insights/professional-learning/refresher-readings/2026/pricing-and-valuation-of-forward-commitments'];
  for(const [course,units] of Object.entries(seminars)){
    for(const [id,seminar] of Object.entries(units)){
      const chapter=book.chapters[course]?.[id];
      if(!chapter)throw new Error('Missing core chapter: '+course+'/'+id);
      chapter.sections.push(...seminar.sections);
      chapter.seminar=seminar;
      if(course==='ethics')chapter.refs=id==='client-duties'?['ethics','suitability']:['ethics'];
      if(course==='quantitative'&&id==='regression')chapter.refs=['curriculum','regression'];
      if(course==='fsa')chapter.refs=id==='revenue-tax'?['analysis','accounting','tax']:['analysis','accounting'];
      if(course==='derivatives'&&['forwards-futures','swaps'].includes(id))chapter.refs=['curriculum','forwards'];
    }
  }
  window.CFA_CORE_SEMINARS=seminars;
})();
